/**
 * test_bank_ipe.js — Itinerario Personal para la Empleabilidad II (IPE II)
 * 5 Unidades × 42 preguntas = 210 preguntas
 * 2º DAW — Banco de preguntas oficial
 */
const TEST_BANK_IPE = [

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 1 — El Proyecto Emprendedor y la Idea de Negocio
  // ════════════════════════════════════════════════════════════════
  { concept_id:"ipe_u1_q1", unit:1, question:"¿Cuál es la diferencia fundamental entre una simple 'idea' y una 'oportunidad de negocio' real?", options:["No hay diferencia","Una idea es solo una ocurrencia abstracta; una oportunidad de negocio resuelve una necesidad insatisfecha real o un problema de un grupo de clientes dispuestos a pagar por la solución de forma viable y rentable","Una oportunidad de negocio siempre requiere inventar algo nunca visto","Las ideas siempre dan dinero"], correct:1, explanation:"Tener una buena idea no basta; debe existir un mercado accesible, demanda solvente y un modelo económico viable.", noShuffle:false },
  { concept_id:"ipe_u1_q2", unit:1, question:"¿Qué es la 'Propuesta de Valor' de un proyecto o empresa?", options:["El precio de las acciones en bolsa","El conjunto único de beneficios y soluciones tangibles que la empresa promete entregar al cliente para resolver sus problemas o satisfacer sus deseos mejor que los competidores","El presupuesto total de gastos","El sueldo de los fundadores"], correct:1, explanation:"Explica claramente por qué el cliente debería elegir tu producto o servicio en lugar de las alternativas del mercado.", noShuffle:false },
  { concept_id:"ipe_u1_q3", unit:1, question:"¿Qué significan las siglas de la matriz de análisis estratégico DAFO (o FODA)?", options:["Datos, Archivos, Ficheros y Objetos","Debilidades, Amenazas, Fortalezas y Oportunidades","Dirección, Administración, Finanzas y Operaciones","Dinero, Acciones, Fondos y Obligaciones"], correct:1, explanation:"Herramienta estratégica que analiza el contexto interno de la empresa (Fortalezas y Debilidades) y el entorno exterior (Oportunidades y Amenazas).", noShuffle:false },
  { concept_id:"ipe_u1_q4", unit:1, question:"En el análisis DAFO, ¿cuáles son los factores de origen INTERNO sobre los que la empresa tiene control directo?", options:["Amenazas y Oportunidades","Fortalezas y Debilidades","Solo las Amenazas","El tipo de interés bancario y las leyes"], correct:1, explanation:"Las fortalezas (ej: equipo técnico cualificado) y debilidades (ej: escaso capital) son internas; oportunidades y amenazas provienen del mercado exterior.", noShuffle:false },
  { concept_id:"ipe_u1_q5", unit:1, question:"¿Qué matriz estratégica se utiliza para actuar sobre los resultados identificados en el análisis DAFO?", options:["Matriz CAME (Corregir debilidades, Afrontar amenazas, Mantener fortalezas y Explotar oportunidades)","Matriz de Ansoff exclusivamente","Matriz BCG","Matriz de Eisenhower"], correct:0, explanation:"CAME transforma el diagnóstico estático del DAFO en un plan de acción estratégico concreto y operativo.", noShuffle:false },
  { concept_id:"ipe_u1_q6", unit:1, question:"¿Qué evalúa el análisis del macroentorno empresarial mediante el marco PESTEL?", options:["El rendimiento de los empleados","Los factores Políticos, Económicos, Sociales, Tecnológicos, Ecológicos/Ambientales y Legales que condicionan el entorno exterior en el que operará la empresa","Los precios de la competencia únicamente","Los servidores del centro de datos"], correct:1, explanation:"PESTEL radiografía las grandes tendencias macro que escapan al control de la empresa pero que determinan sus riesgos y oportunidades.", noShuffle:false },
  { concept_id:"ipe_u1_q7", unit:1, question:"¿Cuáles son las '5 Fuerzas Competitivas' de Michael Porter para analizar el microentorno de un sector?", options:["Lunes, Martes, Miércoles, Jueves y Viernes","1. Rivalidad entre competidores existentes, 2. Amenaza de nuevos entrantes, 3. Poder de negociación de clientes, 4. Poder de negociación de proveedores y 5. Amenaza de productos sustitutivos","Ventas, Compras, Marketing, Finanzas y TI","Precios, Calidad, Tiempo, Soporte y Garantía"], correct:1, explanation:"Determinan el atractivo y la rentabilidad estructural a largo plazo de cualquier sector industrial o de servicios.", noShuffle:false },
  { concept_id:"ipe_u1_q8", unit:1, question:"¿Qué es el 'Business Model Canvas' (Lienzo de Modelo de Negocio) de Alexander Osterwalder?", options:["Un software de diseño gráfico","Una herramienta visual y estratégica de 9 bloques que describe de forma integral y conectada cómo una organización crea, entrega y captura valor","Un contrato societario ante notario","Una hoja de cálculo de nóminas"], correct:1, explanation:"Segmentos de clientes, propuesta de valor, canales, relación con clientes, fuentes de ingresos, recursos clave, actividades clave, socios clave y estructura de costes.", noShuffle:false },
  { concept_id:"ipe_u1_q9", unit:1, question:"¿Qué es el 'Lienzo de la Propuesta de Valor' (Value Proposition Canvas)?", options:["Una factura comercial","Una herramienta de zoom que conecta en detalle dos bloques del Canvas: el perfil del cliente (trabajos/jobs, dolores/pains y alegrías/gains) con el mapa de valor de la empresa (productos, aliviadores de dolor y creadores de alegría)","Un cartel publicitario","Un organigrama empresarial"], correct:1, explanation:"Asegura que las características del producto encajen matemáticamente con las frustraciones y aspiraciones reales del usuario.", noShuffle:false },
  { concept_id:"ipe_u1_q10", unit:1, question:"¿Qué es el 'Plan de Empresa' (Business Plan)?", options:["El horario de apertura del local","Un documento formal y exhaustivo que describe detalladamente los objetivos del proyecto, la estrategia de marketing, el plan de operaciones, los recursos humanos, la forma jurídica y la viabilidad económica y financiera","Un folleto de ventas para clientes","El balance contable del año anterior"], correct:1, explanation:"Sirve como hoja de ruta para los fundadores y como carta de presentación imprescindible para solicitar préstamos, inversores o subvenciones.", noShuffle:false },
  { concept_id:"ipe_u1_q11", unit:1, question:"¿Qué es el 'Punto Muerto' o Umbral de Rentabilidad (Break-Even Point)?", options:["El día que se declara la bancarrota","El volumen exacto de ventas o facturación con el cual los ingresos totales cubren exactamente la totalidad de los costes fijos y variables (beneficio = 0); a partir de ese punto la empresa empieza a generar beneficios netos","La hora de cierre de la oficina","El sueldo del director general"], correct:1, explanation:"Q = Costes Fijos / (Precio de Venta - Coste Variable Unitario). Es el indicador vital de supervivencia inicial de cualquier startup.", noShuffle:false },
  { concept_id:"ipe_u1_q12", unit:1, question:"¿Cuál es la diferencia entre Costes Fijos y Costes Variables en una empresa?", options:["No hay diferencia","Costes Fijos no varían a corto plazo con el volumen de producción o ventas (ej: alquiler del local, sueldos fijos, seguros); Costes Variables aumentan o disminuyen directamente según el nivel de producción (ej: servidores cloud por tráfico, materias primas, comisiones de pago)","Los fijos son en euros y los variables en dólares","Los variables los paga el cliente"], correct:1, explanation:"Una estructura con costes fijos bajos (Lean) reduce el riesgo y permite alcanzar antes el punto muerto.", noShuffle:false },
  { concept_id:"ipe_u1_q13", unit:1, question:"¿Qué es el Plan de Tesorería (Cash Flow Forecast) en la viabilidad financiera?", options:["La caja fuerte física de la oficina","La previsión temporal (mes a mes) de los cobros y pagos monetarios reales de dinero líquido para garantizar que la empresa no incurra en suspensión de pagos por falta de liquidez en cuenta bancaria","La lista de bancos del país","Un gráfico de ventas teóricas"], correct:1, explanation:"'El beneficio es una opinión, la caja es un hecho': muchas empresas rentables en papel quiebran por quedarse sin dinero líquido para pagar nóminas a final de mes.", noShuffle:false },
  { concept_id:"ipe_u1_q14", unit:1, question:"¿Qué diferencia hay entre 'Liquidez' y 'Rentabilidad' en un proyecto empresarial?", options:["Son sinónimos en economía","La Rentabilidad mide la capacidad de generar beneficios sobre la inversión realizada; la Liquidez mide la capacidad inmediata de disponer de dinero efectivo para afrontar las obligaciones de pago a corto plazo","Liquidez es para bancos y rentabilidad para tiendas","La liquidez se mide en porcentaje"], correct:1, explanation:"Una empresa puede ser muy rentable vendiendo mucho a 90 días, pero morir por falta de liquidez a 30 días si no cobra a tiempo.", noShuffle:false },
  { concept_id:"ipe_u1_q15", unit:1, question:"¿Qué es el VAN (Valor Actual Neto) en la evaluación de inversiones?", options:["El valor de una furgoneta de reparto","Un indicador financiero que calcula el valor presente de los flujos de caja futuros generados por una inversión descontados a una tasa de interés, deduciendo el desembolso inicial; si VAN > 0 el proyecto es financieramente viable","El impuesto sobre las ventas","La ganancia bruta de un día"], correct:1, explanation:"Trae el dinero futuro al valor del presente teniendo en cuenta la inflación y el coste de oportunidad del capital.", noShuffle:false },
  { concept_id:"ipe_u1_q16", unit:1, question:"¿Qué es la TIR (Tasa Interna de Retorno)?", options:["Un tipo de interés bancario oficial","La tasa de rentabilidad porcentual anual que genera un proyecto de inversión (la tasa de descuento con la que el VAN es exactamente igual a cero); si la TIR supera el coste del capital, el proyecto es rentable","La tarifa del impuesto de sociedades","El tiempo que tarda en quebrar una empresa"], correct:1, explanation:"Permite comparar la rentabilidad de emprender frente a dejar el dinero en depósitos o bonos del Estado.", noShuffle:false },
  { concept_id:"ipe_u1_q17", unit:1, question:"¿Qué es el 'Payback' o Plazo de Recuperación de una inversión?", options:["La devolución de un producto defectuoso","El tiempo cronológico (meses o años) que tarda la empresa en recuperar el capital inicialmente desembolsado mediante los flujos netos de caja generados por el negocio","El pago con tarjeta de crédito","El dinero que se debe al banco"], correct:1, explanation:"Cuanto más corto sea el plazo de recuperación, menor es el riesgo financiero soportado por los emprendedores.", noShuffle:false },
  { concept_id:"ipe_u1_q18", unit:1, question:"¿Qué es la 'Estrategia del Océano Azul' (Blue Ocean Strategy) de Kim y Mauborgne?", options:["Montar empresas de pesca marina","La estrategia empresarial de crear nuevos espacios de mercado no disputados donde la competencia sea irrelevante, innovando en valor para abrir nueva demanda en lugar de competir en 'océanos rojos' saturados de rivales sangrientos","Vender billetes de barco","Una política ecológica marina"], correct:1, explanation:"Ejemplos como el Cirque du Soleil o Uber reinventaron sectores tradicionales creando un espacio propio sin competidores directos iniciales.", noShuffle:false },
  { concept_id:"ipe_u1_q19", unit:1, question:"¿Qué es la 'Segmentación de Mercado'?", options:["Dividir la oficina en despachos","La división del mercado total en grupos homogéneos y diferenciados de clientes potenciales (por criterios demográficos, geográficos, psicográficos o conductuales) con necesidades y comportamientos de compra similares","Vender a todas las personas del mundo por igual","Una bajada masiva de precios"], correct:1, explanation:"Permite enfocar los recursos de marketing en el 'Target' o público objetivo prioritario en lugar de disparar a ciegas.", noShuffle:false },
  { concept_id:"ipe_u1_q20", unit:1, question:"¿Qué es el 'Customer Discovery' en la metodología de Steve Blank?", options:["Descubrir ladrones de tiendas","El proceso sistemático de salir de la oficina ('Get out of the building') para entrevistar a clientes reales y verificar si las hipótesis de partida sobre el problema y la solución son ciertas o meras ilusiones de los fundadores","Hacer encuestas online anónimas únicamente","Analizar a la competencia"], correct:1, explanation:"Evita el trágico error de construir un producto que nadie necesita ni está dispuesto a comprar.", noShuffle:false },
  { concept_id:"ipe_u1_q21", unit:1, question:"¿Qué es el 'Efecto Red' en modelos de negocio digitales de software?", options:["La velocidad de la conexión por cable","Cuando el valor del servicio para un nuevo usuario aumenta en la medida en que crecen los demás usuarios que ya utilizan la plataforma (ej: redes sociales, marketplaces)","Un fallo en el router","Una caída del servidor"], correct:1, explanation:"Crea barreras de entrada formidables protegiendo a la startup contra nuevos competidores.", noShuffle:false },
  { concept_id:"ipe_u1_q22", unit:1, question:"¿Qué es el 'CAC' (Coste de Adquisición de Clientes)?", options:["El sueldo del director de compras","La cantidad total de dinero invertida en marketing, ventas y publicidad dividida entre el número de clientes nuevos captados en un periodo determinado","El precio de venta del software","El descuento comercial"], correct:1, explanation:"Si tu CAC es de 100€ pero el cliente solo te genera 50€ de beneficio a lo largo de su vida, tu negocio está condenado a quebrar.", noShuffle:false },
  { concept_id:"ipe_u1_q23", unit:1, question:"¿Qué es el 'LTV' (LifeTime Value / Valor de Vida del Cliente)?", options:["La fecha de caducidad del software","El beneficio neto total estimado que un cliente genera a la empresa a lo largo de toda su relación comercial continua antes de darse de baja","La edad del cliente","El precio de la primera compra"], correct:1, explanation:"Regla de oro de las startups viables: la relación LTV/CAC debe ser de al menos 3 a 1 (LTV >= 3x CAC).", noShuffle:false },
  { concept_id:"ipe_u1_q24", unit:1, question:"¿Qué es el 'Churn Rate' (Tasa de Cancelación / Deserción de Clientes)?", options:["El porcentaje de clientes morosos","El porcentaje de suscriptores o clientes que cancelan su cuenta o dejan de comprar tu servicio en un periodo determinado (habitualmente mensual o anual)","El número de clientes nuevos","La tasa de impuestos"], correct:1, explanation:"Un Churn Rate alto actúa como un cubo con agujeros: por muchos clientes nuevos que captes con publicidad, el negocio no puede crecer.", noShuffle:false },
  { concept_id:"ipe_u1_q25", unit:1, question:"¿Qué es el modelo de negocio 'Freemium' en productos de software?", options:["Software completamente gratis para siempre y sin publicidad","Ofrecer una versión básica y funcional del producto de forma 100% gratuita para atraer masa crítica de usuarios, cobrando por características avanzadas, mayor capacidad o soporte profesional (versión Premium)","Un software pirata","Un periodo de prueba de 7 días"], correct:1, explanation:"Modelos como Spotify, GitHub o Dropbox se apoyan en que el 5% de usuarios de pago financia al 95% de usuarios gratuitos.", noShuffle:false },
  { concept_id:"ipe_u1_q26", unit:1, question:"¿Qué es el modelo de negocio de 'Suscripción Recurrente' (SaaS)?", options:["Comprar una licencia perpetua en CD","Cobrar una cuota periódica (mensual o anual) a cambio del acceso continuo al software alojado en la nube, actualizaciones permanentes y soporte técnico","Pagar por horas de trabajo","Un contrato de alquiler de oficinas"], correct:1, explanation:"Proporciona ingresos altamente predecibles (MRR - Monthly Recurring Revenue) muy valorados por inversores.", noShuffle:false },
  { concept_id:"ipe_u1_q27", unit:1, question:"¿Qué es el 'Product Hunt' en el ecosistema de lanzamiento de productos de software?", options:["Una cacería de animales","Una plataforma web de referencia global donde creadores y desarrolladores de software lanzan sus nuevos productos digitales a una comunidad de 'early adopters' que votan y comentan las mejores herramientas del día","Una tienda de informática","Un congreso presencial"], correct:1, explanation:"Conseguir el 'Product of the Day' en Product Hunt puede generar miles de registros de usuarios en 24 horas a coste cero.", noShuffle:false },
  { concept_id:"ipe_u1_q28", unit:1, question:"¿Qué es un 'Early Adopter' (Adoptante Temprano)?", options:["Una persona que madruga mucho","Clientes pioneros visionarios que tienen un problema tan urgente y doloroso que están dispuestos a probar y pagar por un producto imperfecto en sus primeras fases de desarrollo y dar feedback valioso a los creadores","Un inversor millonario","Un usuario que solo compra ofertas"], correct:1, explanation:"Son los primeros clientes a los que debe dirigirse una startup según la Curva de Adopción de Innovaciones de Rogers.", noShuffle:false },
  { concept_id:"ipe_u1_q29", unit:1, question:"¿Qué es el 'Elevator Pitch' (Discurso de Ascensor)?", options:["Un discurso dentro de un montacargas","Una presentación verbal ultra-sintética, persuasiva y memorable de la idea de negocio de entre 30 y 90 segundos diseñada para captar la atención inmediata de un inversor o cliente clave y conseguir una reunión formal posterior","Un folleto publicitario","Una conferencia de dos horas"], correct:1, explanation:"Debe responder en segundos: ¿Qué problema resuelves? ¿Para quién? ¿Cómo lo resuelves? ¿Por qué tu equipo? y ¿Qué pides?", noShuffle:false },
  { concept_id:"ipe_u1_q30", unit:1, question:"¿Qué es el 'Pitch Deck' en una ronda de búsqueda de financiación?", options:["El suelo de la oficina","Una presentación visual estructurada en 10-15 diapositivas que sintetiza el problema, la solución, el tamaño de mercado, el modelo de negocio, la tracción demostrada, el equipo y la propuesta financiera para convencer a inversores de capital riesgo","Un contrato societario","Un plan contable de 200 páginas"], correct:1, explanation:"Es el documento visual de cabecera que los inversores analizan en menos de 3 minutos antes de decidir si invierten.", noShuffle:false },
  { concept_id:"ipe_u1_q31", unit:1, question:"¿Qué es la 'Tracción' (Traction) de una startup?", options:["La fuerza de rozamiento de las ruedas","La prueba cuantitativa y medible de que el mercado tiene una demanda real por tu producto, demostrada mediante métricas de usuarios activos, crecimiento de ingresos recurrentes, pedidos o acuerdos comerciales firmados","La potencia de los ordenadores","El tiempo transcurrido desde la fundación"], correct:1, explanation:"Los inversores no invierten en ideas abstractas; invierten en tracción demostrada y velocidad de ejecución.", noShuffle:false },
  { concept_id:"ipe_u1_q32", unit:1, question:"¿Qué es el 'Bootstrapping' en la financiación de startups?", options:["Comprar botas de trabajo caras","Fundar, financiar y hacer crecer la empresa utilizando exclusivamente los propios ahorros personales de los fundadores y los ingresos generados por los primeros clientes, sin recurrir a inversores externos ni deuda bancaria","Pedir un préstamo al 0%","Una subvención europea a fondo perdido"], correct:1, explanation:"Conserva el 100% de la propiedad y el control estratégico en manos de los creadores a costa de un crecimiento más orgánico.", noShuffle:false },
  { concept_id:"ipe_u1_q33", unit:1, question:"¿Qué representan las '3 F' (Friends, Family and Fools) en las fases iniciales de financiación?", options:["Tres bancos internacionales","La primera ronda de capital semilla informal procedente del entorno más cercano del emprendedor (amigos, familiares y entusiastas) que invierten por confianza personal antes de que existan métricas sólidas","Fondos de capital riesgo agresivos","Un préstamo del Estado"], correct:1, explanation:"Aporta el primer combustible para desarrollar el MVP y validar las primeras hipótesis de mercado.", noShuffle:false },
  { concept_id:"ipe_u1_q34", unit:1, question:"¿Qué es un 'Business Angel' (Inversor Ángel)?", options:["Una figura religiosa benevolente","Una persona física con experiencia empresarial y patrimonio propio que invierte su capital privado en startups en etapas tempranas (semilla), aportando además contactos comerciales, asesoramiento estratégico y 'Smart Money'","Un directivo de un banco público","Un prestamista con intereses altos"], correct:1, explanation:"Su valor radica tanto en el dinero aportado como en su mentoría y agenda de contactos corporativos.", noShuffle:false },
  { concept_id:"ipe_u1_q35", unit:1, question:"¿Qué es el 'Venture Capital' (Capital Riesgo)?", options:["Apostar en el casino","Entidades financieras y fondos profesionales que gestionan dinero de terceros para invertir en empresas no cotizadas con alto potencial de crecimiento exponencial y alto riesgo a cambio de una participación accionarial importante","Préstamos hipotecarios de bancos","Subvenciones de desempleo"], correct:1, explanation:"Buscan desinversiones multimillonarias (salida a bolsa o venta a una multinacional) en horizontes de 5 a 10 años.", noShuffle:false },
  { concept_id:"ipe_u1_q36", unit:1, question:"¿Qué son los préstamos participativos de ENISA en España?", options:["Hipotecas para comprar oficinas","Préstamos financieros públicos sin avales ni garantías reales concedidos por la Empresa Nacional de Innovación a pymes y startups viables e innovadoras, donde los intereses están ligados a la rentabilidad del negocio","Créditos bancarios ordinarios","Subvenciones que no se devuelven"], correct:1, explanation:"Es uno de los principales motores públicos de financiación no dilutiva para emprendedores tecnológicos en España.", noShuffle:false },
  { concept_id:"ipe_u1_q37", unit:1, question:"¿Qué significa que una financiación sea 'No Dilutiva'?", options:["Que no se mezcla con agua","Financiación (como subvenciones, ayudas públicas o créditos ENISA) que aporta dinero a la empresa sin exigir a cambio acciones o participación en el capital social, preservando el porcentaje de los fundadores","Un préstamo a interés cero","Una donación caritativa"], correct:1, explanation:"A diferencia de los inversores de capital riesgo, la financiación no dilutiva no reduce el porcentaje accionarial de los creadores.", noShuffle:false },
  { concept_id:"ipe_u1_q38", unit:1, question:"¿Qué es un 'Pacto de Socios' (Founders Agreement) y por qué debe firmarse al inicio del proyecto?", options:["Un contrato de compraventa con clientes","Un acuerdo privado y vinculante entre los fundadores que regula aspectos críticos que no figuran en los estatutos: reparto de participaciones, dedicación de horas, propiedad intelectual, cláusulas de salida y resolución de conflictos","Un trámite notarial optativo de cortesía","El contrato de trabajo laboral"], correct:1, explanation:"Previene el colapso de la startup si uno de los socios abandona el proyecto al tercer mes exigiendo quedarse con la mitad de las acciones.", noShuffle:false },
  { concept_id:"ipe_u1_q39", unit:1, question:"¿Qué es la cláusula de 'Vesting' en un pacto de socios?", options:["Comprar ropa de trabajo para el equipo","Un mecanismo contractual donde los fundadores o empleados clave no adquieren la propiedad definitiva de sus acciones de golpe, sino que las consolidan progresivamente a lo largo del tiempo (ej: 4 años con 1 año de 'Cliff') condicionado a su permanencia en la empresa","El sueldo fijo mensual","Una póliza de seguros"], correct:1, explanation:"Si un socio se marcha a los seis meses, pierde las acciones no consolidadas evitando bloqueos accionariales destructivos.", noShuffle:false },
  { concept_id:"ipe_u1_q40", unit:1, question:"¿Qué es el 'Cliff' en una cláusula de Vesting?", options:["Un acantilado peligroso","El periodo mínimo inicial de permanencia (habitualmente 1 año) antes del cual el socio o empleado no consolida ninguna acción; al cumplir el año consolida el primer 25% y el resto mes a mes","La fecha de quiebra","El primer dividendo pagado"], correct:1, explanation:"Asegura que quien abandone el proyecto de forma prematura no se lleve ninguna participación de la compañía.", noShuffle:false },
  { concept_id:"ipe_u1_q41", unit:1, question:"¿Qué es la 'Propiedad Intelectual' del código de software desarrollado por los fundadores?", options:["Un impuesto sobre el código","El conjunto de derechos morales y patrimoniales protegidos por ley que otorga a los autores el control exclusivo sobre la copia, distribución y comercialización del software que han creado","El registro del dominio .com","La factura de los servidores"], correct:1, explanation:"El pacto de socios debe incluir la cesión expresa e irrevocable de la propiedad del código a la sociedad mercantil constituida.", noShuffle:false },
  { concept_id:"ipe_u1_q42", unit:1, question:"¿Cuál es la primera causa de fracaso de las startups según los estudios de CB Insights?", options:["Quedarse sin dinero de repente sin avisar","Construir un producto que no responde a ninguna necesidad real del mercado (No Market Need: 35%-42% de los fracasos)","Peleas entre socios únicamente","Ataques informáticos"], correct:1, explanation:"Enamorarse de una solución técnica brillante sin verificar previamente que existe un cliente real dispuesto a pagar por ella es el error fatal más extendido.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 2 — Búsqueda de Empleo en el Sector IT y Marca Personal
  // ════════════════════════════════════════════════════════════════
  { concept_id:"ipe_u2_q1", unit:2, question:"¿Qué es el 'Mercado Oculto de Empleo' (Hidden Job Market) en el sector tecnológico?", options:["Ofertas de trabajo ilegales en la dark web","La inmensa mayoría de vacantes laborales (entre el 70% y el 80%) que nunca llegan a publicarse abiertamente en portales de empleo y se cubren mediante contactos profesionales, networking, recomendaciones internas y búsqueda directa de reclutadores (headhunters)","Puestos de trabajo sin sueldo","Ofertas de empleo de empresas que ya han quebrado"], correct:1, explanation:"Limitar la búsqueda únicamente a enviar currículums ciegos a portales públicos ignora el 80% de las oportunidades reales.", noShuffle:false },
  { concept_id:"ipe_u2_q2", unit:2, question:"¿Qué es la 'Marca Personal' (Personal Branding) para un desarrollador de software?", options:["Diseñar un logotipo propio de pago","La percepción profesional pública y reputación que el sector, reclutadores y colegas tienen sobre tus competencias, valores, especialización y calidad de trabajo a través de tu presencia digital (GitHub, LinkedIn, blog, proyectos reales)","Tener miles de seguidores en Instagram","El título universitario oficial"], correct:1, explanation:"'Tu marca personal es lo que dicen de ti cuando sales de la habitación' (Jeff Bezos): demuestra lo que eres capaz de construir.", noShuffle:false },
  { concept_id:"ipe_u2_q3", unit:2, question:"¿Por qué el perfil de GitHub actúa como el verdadero portfolio técnico de un desarrollador web?", options:["Porque es donde se guarda el DNI digital","Porque permite a los líderes técnicos examinar directamente la calidad real de tu código: arquitectura, commits limpios y descriptivos, documentación en README, tests y colaboración en proyectos open-source reales","Porque GitHub te paga por cada commit","Porque sustituye al contrato laboral"], correct:1, explanation:"Los reclutadores técnicos prefieren ver 2 proyectos pulidos y desplegados en producción con código en GitHub que 5 páginas de texto de currículum.", noShuffle:false },
  { concept_id:"ipe_u2_q4", unit:2, question:"¿Qué elementos son imprescindibles en un archivo README.md profesional de un proyecto en GitHub?", options:["El color favorito del programador","Título claro, descripción del problema que resuelve, demo online funcional enlazada (deploy), tecnologías utilizadas (stack), captura de pantalla o GIF interactivo e instrucciones de instalación y ejecución en local","El código fuente entero en texto plano","Una foto del desarrollador"], correct:1, explanation:"El README es el escaparate: un proyecto sin documentación clara suele ser descartado en 10 segundos por los reclutadores.", noShuffle:false },
  { concept_id:"ipe_u2_q5", unit:2, question:"¿Cuál es la longitud recomendada de un Currículum Vitae (CV) para un perfil junior o intermedio en el sector tecnológico?", options:["5 o 6 páginas con todo detalle de la infancia","Máximo 1 página (o excepcionalmente 2 páginas para perfiles senior con más de 10 años de experiencia relevante), conciso, escaneable visualmente y directo al grano","10 páginas con certificados escaneados","Un párrafo de dos líneas"], correct:1, explanation:"Los reclutadores dedican de media entre 6 y 10 segundos a escanear un CV en el primer filtro.", noShuffle:false },
  { concept_id:"ipe_u2_q6", unit:2, question:"¿Qué es un sistema 'ATS' (Applicant Tracking System) utilizado por los departamentos de selección?", options:["Un software para espiar ordenadores","Un software automatizado que gestiona candidaturas, parsea y escanea currículums en busca de palabras clave técnicas específicas (tecnologías, frameworks, herramientas) filtrando a los candidatos antes de que un humano lea el CV","Un programa que redacta contratos","Un antivirus para correos"], correct:1, explanation:"Para superar el filtro ATS, el CV debe estar en formato PDF legible por máquina, sin diseños complejos en columnas múltiples ni imágenes que tapen texto, e incluir las palabras clave exactas de la oferta.", noShuffle:false },
  { concept_id:"ipe_u2_q7", unit:2, question:"¿Cómo deben redactarse los logros e hitos en la sección de experiencia o proyectos de un CV técnico para generar máximo impacto?", options:["Describiendo solo tareas pasivas rutinarias (ej: 'Hice una web')","Utilizando verbos de acción y cuantificando los resultados con métricas o porcentajes objetivos (ej: 'Desarrollé una API REST en PHP/Laravel que redujo el tiempo de respuesta en un 35% y gestionó 10.000 peticiones diarias')","Poniendo adjetivos elogiosos sobre uno mismo","Copiando la descripción de la Wikipedia"], correct:1, explanation:"La fórmula de Google 'Conseguí X medido por Y haciendo Z' demuestra impacto tangible para el negocio.", noShuffle:false },
  { concept_id:"ipe_u2_q8", unit:2, question:"¿Qué apartado del perfil de LinkedIn es el más determinante para aparecer en las búsquedas de los reclutadores de TI?", options:["La foto de fondo decorativa","El Titular profesional (Headline): debe incluir el rol exacto y las tecnologías clave de especialización (ej: 'Full-Stack Developer | PHP · Laravel · JavaScript · Docker | 2º DAW') en lugar de solo poner 'En búsqueda activa'","El número de contactos","El nombre del instituto"], correct:1, explanation:"Los reclutadores buscan por palabras clave exactas en el titular y el extracto.", noShuffle:false },
  { concept_id:"ipe_u2_q9", unit:2, question:"¿Qué portales de empleo están especializados exclusivamente en el sector tecnológico y de startups en España y Europa?", options:["Milanuncios","Manfred, Circular, Get on Board, Welcome to the Jungle y Joppy","Portales generalistas de empleo temporal únicamente","Páginas amarillas"], correct:1, explanation:"Plataformas como Manfred y Circular ofrecen ofertas técnicas transparentes con rango salarial publicado y condiciones laborales claras.", noShuffle:false },
  { concept_id:"ipe_u2_q10", unit:2, question:"¿Qué es el 'Networking' profesional en la búsqueda de empleo tecnológico?", options:["Instalar cables de red Ethernet","El proceso activo y genuino de construir, cultivar y mantener relaciones profesionales de confianza mutua a largo plazo con colegas, profesores, profesionales y reclutadores del sector","Enviar mensajes de spam pidiendo trabajo a desconocidos","Coleccionar contactos en redes sin interactuar"], correct:1, explanation:"Participar en meetups locales de tecnología, conferencias y comunidades de Discord abre puertas directas al mercado oculto de empleo.", noShuffle:false },
  { concept_id:"ipe_u2_q11", unit:2, question:"¿Qué es una 'Carta de Presentación' (Cover Letter) adaptada a una oferta concreta?", options:["Una carta pidiendo dinero","Un documento breve y personalizado que acompaña al CV donde explicas por qué te apasiona esa empresa específica, cómo tus competencias resuelven sus retos actuales y qué valor diferencial puedes aportar a su equipo","Una copia exacta del CV en texto largo","Una plantilla genérica enviada a 50 empresas a la vez"], correct:1, explanation:"Demuestra que has investigado a la empresa y que no estás aplicando de forma automática e indiferente.", noShuffle:false },
  { concept_id:"ipe_u2_q12", unit:2, question:"¿Qué papel juegan las 'Comunidades Tecnológicas' (Meetups, Discord, foros) en la inserción laboral de un desarrollador junior?", options:["Hacer perder el tiempo","Son foros extraordinarios donde conocer a líderes técnicos de empresas locales, enterarse de contrataciones antes de que se publiquen, resolver dudas técnicas complejas y encontrar mentores profesionales","Cobrar dinero por hablar","Aprender a jugar a videojuegos"], correct:1, explanation:"Muchos líderes técnicos contratan a candidatos activos que han demostrado curiosidad y compromiso en comunidades técnicas.", noShuffle:false },
  { concept_id:"ipe_u2_q13", unit:2, question:"¿Qué es un 'Headhunter' o 'Tech Recruiter'?", options:["Un cazador de animales","Un profesional o consultor de selección especializado en buscar, evaluar y reclutar talento técnico cualificado para empresas clientes, habitualmente mediante búsqueda proactiva en LinkedIn y GitHub","El jefe de personal de la empresa","Un inspector de trabajo"], correct:1, explanation:"Establecer relación con reclutadores de TI permite acceder a oportunidades exclusivas no publicitadas.", noShuffle:false },
  { concept_id:"ipe_u2_q14", unit:2, question:"¿Por qué se debe evitar incluir información personal irrelevante (estado civil, religión, dirección física completa o fecha de nacimiento) en un CV moderno?", options:["Porque no caben en la hoja","Para prevenir sesgos inconscientes o discriminaciones en la selección y por cumplimiento con las mejores prácticas de privacidad y contratación inclusiva","Porque es ilegal usar texto","Para que parezca más corto"], correct:1, explanation:"El proceso de selección debe evaluar estrictamente competencias profesionales y adecuación técnica al puesto.", noShuffle:false },
  { concept_id:"ipe_u2_q15", unit:2, question:"¿Qué es un 'Portfolio Web Personal' alojado en un dominio propio?", options:["Una tienda de venta de ordenadores","Una página web interactiva desarrollada por el propio candidato donde muestra sus mejores proyectos desplegados, biografía profesional, enlaces a GitHub/LinkedIn y formulario de contacto","Un perfil de Facebook","Una carpeta compartida de Google Drive"], correct:1, explanation:"Un portfolio responsive, rápido y pulido estéticamente es la prueba definitiva de las capacidades de maquetación y desarrollo de un estudiante de DAW.", noShuffle:false },
  { concept_id:"ipe_u2_q16", unit:2, question:"¿Por qué es fundamental que los proyectos incluidos en el portfolio estén desplegados en vivo (con URL pública funcional)?", options:["Porque a los reclutadores les gusta navegar por internet","Porque los reclutadores y directores técnicos rara vez tienen tiempo de clonar un repositorio, configurar Docker y levantar una base de datos local para ver si funciona tu aplicación; quieren pulsar un enlace y probarla de inmediato","Porque el código en GitHub no se puede leer","Porque es obligatorio para el título"], correct:1, explanation:"Un proyecto desplegado en plataformas gratuitas (Vercel, Render, Railway) demuestra que dominas el ciclo completo hasta producción.", noShuffle:false },
  { concept_id:"ipe_u2_q17", unit:2, question:"¿Qué es la 'Candidatura Espontánea' en la búsqueda de empleo?", options:["Presentarse en la oficina sin avisar con una maleta","El envío proactivo y respetuoso de una propuesta de valor personalizada a una empresa que admiras, dirigiéndote a la persona adecuada aunque no tengan ninguna vacante publicada formalmente en ese momento","Esperar a que te llamen por teléfono","Publicar un anuncio en el periódico"], correct:1, explanation:"Si tu propuesta coincide con una necesidad no cubierta que la empresa pensaba resolver el mes que viene, evitas toda competencia.", noShuffle:false },
  { concept_id:"ipe_u2_q18", unit:2, question:"¿Qué es el 'Social Selling Index' (SSI) de LinkedIn?", options:["Una comisión por vender cursos","Una puntuación de 0 a 100 que mide la efectividad de un profesional en establecer su marca personal, encontrar a las personas adecuadas, interactuar con información valiosa y crear relaciones de confianza en la red","El número de mensajes enviados","El precio de la suscripción Premium"], correct:1, explanation:"Tener un perfil completo y compartir reflexiones técnicas de valor eleva el alcance orgánico de tus publicaciones.", noShuffle:false },
  { concept_id:"ipe_u2_q19", unit:2, question:"¿Qué tipo de proyectos NO se recomienda poner como proyectos estrella destacados en un portfolio de desarrollo web?", options:["Proyectos completos con base de datos y autenticación propia","Los tutoriales genéricos clonados paso a paso sin modificaciones personales (ej: la típica 'To-Do list' básica o la 'calculadora' de un curso de YouTube) que no demuestran criterio propio","Proyectos que resuelven un problema a una empresa local real","Aplicaciones desplegadas con tests automatizados"], correct:1, explanation:"Los proyectos con usuarios reales o que abordan problemas originales destacan inmediatamente frente a miles de candidatos con la misma lista de tareas básica.", noShuffle:false },
  { concept_id:"ipe_u2_q20", unit:2, question:"¿Qué significa el término 'T-Shaped Professional' (Profesional con Perfil en T)?", options:["Un programador que viste camisetas con una T","Un perfil profesional que posee conocimientos amplios y transversales en muchas áreas de la tecnología (la barra horizontal de la T: frontend, backend, redes, cloud, agilidad) y una especialización técnica muy profunda en un área concreta (la barra vertical: ej: APIs en PHP o arquitectura frontend)","Un trabajador a tiempo parcial","Un consultor de telecomunicaciones"], correct:1, explanation:"Es el perfil más codiciado en equipos modernos por su capacidad de entender el conjunto colaborando fluidamente mientras aporta maestría técnica específica.", noShuffle:false },
  { concept_id:"ipe_u2_q21", unit:2, question:"¿Qué es una 'Hackathon' y cómo potencia la búsqueda de empleo?", options:["Un hackeo masivo a un banco","Un maratón colaborativo de desarrollo de software (habitualmente de 24 o 48 horas intensivas) donde equipos multidisciplinares crean soluciones funcionales a retos propuestos, sirviendo como escaparate directo ante empresas patrocinadoras que reclutan talento en vivo","Una reunión de ciberdelincuentes","Un curso teórico de programación"], correct:1, explanation:"Demuestra en la práctica cómo trabajas bajo presión, tu capacidad de aprendizaje ágil y tu trabajo en equipo.", noShuffle:false },
  { concept_id:"ipe_u2_q22", unit:2, question:"¿Qué importancia tiene la 'Contribución a Proyectos de Código Abierto' (Open Source) en el currículum de un programador?", options:["No tiene ninguna importancia","Demuestra de forma pública y auditable que sabes leer código ajeno complejo, adaptarte a estilos de otros equipos, colaborar mediante Git, recibir y responder a code reviews y aportar valor a herramientas usadas por miles de personas","Es un requisito legal para trabajar","Sirve para no pagar licencias de software"], correct:1, explanation:"Incluso corregir bugs menores o mejorar la documentación en repositorios reconocidos eleva enormemente tu credibilidad técnica.", noShuffle:false },
  { concept_id:"ipe_u2_q23", unit:2, question:"¿Qué es el 'Salario Emocional' en una propuesta de empleo IT?", options:["Cobrar con abrazos en lugar de dinero","La retribución no económica que satisface las necesidades personales y profesionales del trabajador: flexibilidad horaria, teletrabajo real, oportunidades de formación continua, buen clima laboral y planes de carrera claros","El aguinaldo navideño","Un complemento de peligrosidad"], correct:1, explanation:"En perfiles tecnológicos cotizados, el salario emocional suele ser el factor decisivo para decantar la balanza entre ofertas de sueldo similar.", noShuffle:false },
  { concept_id:"ipe_u2_q24", unit:2, question:"¿Qué es una 'Empresa Remota Primero' (Remote-First) frente a una empresa presencial tradicional?", options:["Una empresa que no tiene trabajadores","Una organización diseñada desde su base para que todas sus comunicaciones, procesos y flujos de trabajo sean asíncronos y digitales por defecto, permitiendo a los empleados trabajar desde cualquier lugar geográfico sin desventajas respecto a la oficina física","Una empresa que trabaja en el campo","Una compañía de mudanzas"], correct:1, explanation:"Abre el mercado laboral global permitiendo a desarrolladores españoles trabajar para empresas del norte de Europa o EE.UU. con salarios competitivos desde su ciudad.", noShuffle:false },
  { concept_id:"ipe_u2_q25", unit:2, question:"¿Qué es el 'Efecto Primacía y Recencia' en el diseño de un currículum vitae?", options:["Los colores elegidos para el encabezado","El fenómeno cognitivo por el que los evaluadores recuerdan y prestan muchísima mayor atención a los elementos colocados al principio (primacía) y al final (recencia) del documento","La fecha de nacimiento","El tipo de letra"], correct:1, explanation:"Los proyectos más impactantes y las tecnologías más relevantes deben ubicarse en la parte superior de la primera página.", noShuffle:false },
  { concept_id:"ipe_u2_q26", unit:2, question:"¿Qué es la 'Identidad Digital Profesional' en redes sociales abiertas?", options:["Tener dos cuentas de usuario","La huella pública de opiniones, publicaciones y conductas que cualquier reclutador puede encontrar sobre ti al buscar tu nombre en Google antes de citarte a una entrevista","El DNI electrónico","Un certificado de software"], correct:1, explanation:"Publicaciones ofensivas, comentarios tóxicos o descalificaciones en foros pueden arruinar un proceso de selección en segundos.", noShuffle:false },
  { concept_id:"ipe_u2_q27", unit:2, question:"¿Por qué se debe evitar el uso de 'barras de progreso porcentuales' para indicar el nivel de idiomas o tecnologías en un CV (ej: 'JavaScript 85%')?", options:["Porque ocupan mucho espacio en la hoja","Porque son métricas subjetivas y vacías de significado real que nadie puede verificar (¿qué significa un 85% de un lenguaje como JS?) y restan seriedad profesional","Porque los porcentajes están prohibidos en diseño","Porque los ATS no leen números"], correct:1, explanation:"Es mucho mejor listar las tecnologías dominadas contextualizadas dentro de los proyectos reales construidos con ellas.", noShuffle:false },
  { concept_id:"ipe_u2_q28", unit:2, question:"¿Qué es una 'Recomendación en LinkedIn' y qué valor aporta a un perfil técnico junior?", options:["Un 'Me gusta' en una publicación","Un testimonio público firmado por un antiguo profesor, tutor de prácticas en empresa (FCT/Dual) o compañero que avala con palabras concretas tu ética de trabajo, capacidad técnica y actitud en equipo","Un mensaje privado de felicitación","Una insignia de pago"], correct:1, explanation:"Aporta prueba social externa incontestable que valida lo que afirmas en tu currículum.", noShuffle:false },
  { concept_id:"ipe_u2_q29", unit:2, question:"¿Qué papel desempeña un 'Blog Técnico' o la publicación de artículos en plataformas como dev.to o Medium en la carrera de un desarrollador?", options:["Ganar dinero con anuncios inmediatamente","Posiciona tu autoridad técnica, consolida tu propio aprendizaje al explicar conceptos complejos a otros de forma didáctica y demuestra capacidad de comunicación escrita y rigor conceptual","Sustituye al título de FP","Un diario íntimo personal"], correct:1, explanation:"'Si quieres aprender algo, escríbelo para que otros lo entiendan': es un imán de ofertas laborales inbound.", noShuffle:false },
  { concept_id:"ipe_u2_q30", unit:2, question:"¿Qué es el 'Inbound Recruitment' en el mercado laboral de software?", options:["Salir a repartir currículums en mano","La estrategia por la cual son las empresas y reclutadores quienes contactan directamente al candidato con ofertas de trabajo atraídos por su visibilidad, proyectos en GitHub, publicaciones técnicas y reputación en redes","Contratar trabajadores extranjeros","Un despido colectivo"], correct:1, explanation:"Invertir en marca personal permite pasar de buscar empleo activamente a elegir entre propuestas entrantes de calidad.", noShuffle:false },
  { concept_id:"ipe_u2_q31", unit:2, question:"¿Qué es el 'Glassdoor' o portales de valoración de empresas por parte de empleados?", options:["Una tienda de cristalería online","Plataformas donde empleados actuales y antiguos comparten de forma anónima opiniones sobre la cultura corporativa, salarios reales de los puestos, estilo de liderazgo y preguntas reales formuladas en sus procesos de selección","Un portal de compras","Una base de datos de auditoría fiscal"], correct:1, explanation:"Permite al candidato investigar la reputación interna de la empresa antes de aceptar una oferta y evitar entornos tóxicos.", noShuffle:false },
  { concept_id:"ipe_u2_q32", unit:2, question:"¿Qué es la 'Firma Profesional de Correo' al enviar candidaturas?", options:["Escribir el nombre con caligrafía artística","Un pie de firma limpio y profesional al final del email con tu nombre completo, rol técnico (ej: Desarrollador Web Full-Stack), teléfono, enlaces limpios a tu LinkedIn, GitHub y Portfolio web","Un archivo adjunto pesado","Un logotipo enorme animado"], correct:1, explanation:"Facilita al reclutador un acceso instantáneo a todos tus canales profesionales con un solo clic.", noShuffle:false },
  { concept_id:"ipe_u2_q33", unit:2, question:"¿Qué significa que una oferta de trabajo IT busque un perfil 'Junior' pero pida 5 años de experiencia?", options:["Que la empresa ofrece un sueldo excelente","Una señal de alerta (Red Flag) de una oferta mal redactada o de una empresa que busca un profesional intermedio/senior pagándole un salario precario de junior","Un requisito oficial del ministerio","Un error de imprenta inevitable"], correct:1, explanation:"Un perfil junior se define por tener entre 0 y 2 años de experiencia profesional y necesitar supervisión técnica formativa.", noShuffle:false },
  { concept_id:"ipe_u2_q34", unit:2, question:"¿Qué es el 'Síndrome del Impostor' tan frecuente en estudiantes y profesionales del desarrollo de software?", options:["Un virus informático que borra el código","El fenómeno psicológico por el cual una persona competente se siente incapaz, duda de sus propios logros y experimenta un miedo constante e irracional a ser 'descubierta' como un fraude frente a los demás","Creerse mejor que todos los compañeros","Un problema de memoria a corto plazo"], correct:1, explanation:"La inmensidad del ecosistema tecnológico hace que nadie lo sepa todo; normalizar que no saber algo no te hace incompetente es clave para la salud mental.", noShuffle:false },
  { concept_id:"ipe_u2_q35", unit:2, question:"¿Cómo se debe titular el archivo PDF de un currículum vitae al enviarlo por correo?", options:["CV.pdf o Curriculo_final_v2_definitivo.pdf","Con tu nombre profesional claro: Nombre_Apellido_CV_FullStack_2026.pdf","documento_sin_titulo.pdf","curriculum_vitae_nuevo.pdf"], correct:1, explanation:"Facilita que el reclutador lo guarde y lo localice en segundos dentro de su carpeta de descargas sin confundirlo con otros cien archivos llamados 'CV.pdf'.", noShuffle:false },
  { concept_id:"ipe_u2_q36", unit:2, question:"¿Qué es el 'Continuous Learning' (Aprendizaje Continuo / Lifelong Learning) en el sector informático?", options:["Estar estudiando en el instituto toda la vida","La actitud y hábito profesional proactivo de actualizar y aprender permanentemente nuevas tecnologías, frameworks y herramientas a lo largo de toda la carrera laboral debido a la rápida obsolescencia del sector","Aprender solo lo que manda el jefe","Hacer un curso cada diez años"], correct:1, explanation:"La competencia más valiosa de un graduado de DAW no es conocer un framework concreto de hoy, sino su capacidad contrastada de aprender cualquier tecnología nueva mañana.", noShuffle:false },
  { concept_id:"ipe_u2_q37", unit:2, question:"¿Qué es la 'Matriz de Habilidades' (Skills Matrix) personal en el plan de desarrollo profesional?", options:["Un examen de matemáticas","Una herramienta de autoevaluación visual donde identificas tus competencias técnicas y blandas actuales contrastándolas con las exigidas por las ofertas de empleo objetivo, detectando vacíos formativos a cubrir","Un organigrama empresarial","El horario de clases"], correct:1, explanation:"Permite trazar un plan de estudio individualizado y focalizado en las tecnologías que el mercado laboral realmente demanda.", noShuffle:false },
  { concept_id:"ipe_u2_q38", unit:2, question:"¿Qué papel juegan las 'Certificaciones Profesionales' oficiales (ej: AWS Certified Cloud Practitioner, Scrum Master, Docker)?", options:["Sustituyen a los títulos universitarios","Acreditan formalmente mediante exámenes estandarizados y rigurosos que posees conocimientos técnicos verificados en una tecnología de un proveedor líder, enriqueciendo el perfil junior","Son títulos obligatorios para programar","No tienen ningún valor en el mercado"], correct:1, explanation:"Diferencian el currículum de un recién graduado demostrando iniciativa de especialización y compromiso profesional.", noShuffle:false },
  { concept_id:"ipe_u2_q39", unit:2, question:"¿Por qué se debe adaptar el currículum a cada oferta de empleo individual en lugar de enviar siempre el mismo archivo estándar masivamente?", options:["Porque es obligatorio por ley","Porque permite destacar en primer plano las tecnologías, proyectos y logros que coinciden exactamente con los requisitos clave que la empresa solicita en ese anuncio concreto, multiplicando la tasa de respuesta","Para cambiar el color del documento","Para no aburrirse"], correct:1, explanation:"Enviar 10 candidaturas meticulosamente adaptadas e investigadas consigue muchísimas más entrevistas que enviar 100 CVs genéricos al azar.", noShuffle:false },
  { concept_id:"ipe_u2_q40", unit:2, question:"¿Qué es un 'Podcast Técnico' o una charla en un Meetup impartida por un recién graduado?", options:["Un programa de radio generalista","Una excelente iniciativa de marca personal donde compartes lo que has aprendido desarrollando tu proyecto final de ciclo (TFG/Proyecto intermodular), demostrando capacidad de comunicación y pasión por la tecnología","Una clase particular de pago","Un debate político"], correct:1, explanation:"Diferencia radicalmente tu perfil frente a candidatos que se limitan a enviar currículums pasivos.", noShuffle:false },
  { concept_id:"ipe_u2_q41", unit:2, question:"¿Qué es el 'Efecto Halo' en la primera impresión de un portfolio web?", options:["Un resplandor alrededor de las imágenes","La impresión inmediata de profesionalidad, cuidado por el detalle y calidad estética que transmite una web rápida y bien maquetada en los primeros 5 segundos, predisponiendo positivamente al evaluador hacia el código interno","Un fallo en los estilos de CSS","Un filtro de Instagram"], correct:1, explanation:"Un diseño descuidado o con enlaces rotos hace que el evaluador asuma que el código backend también será descuidado.", noShuffle:false },
  { concept_id:"ipe_u2_q42", unit:2, question:"¿Cuál es la actitud correcta ante el rechazo en un proceso de selección IT?", options:["Enfadarse e insultar a la empresa en redes","Agradecer profesionalmente el tiempo dedicado, solicitar educadamente feedback constructivo sobre puntos de mejora técnica y mantener abierta la relación en LinkedIn para futuras oportunidades cuando el perfil madure","No volver a enviar currículums nunca más","Borrar la cuenta de GitHub"], correct:1, explanation:"El rechazo es parte natural del proceso: un 'no' hoy puede convertirse en una llamada directa para otra vacante dentro de seis meses si dejas una impresión impecable.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 3 — Procesos de Selección, Pruebas Técnicas y Entrevista de Trabajo
  // ════════════════════════════════════════════════════════════════
  { concept_id:"ipe_u3_q1", unit:3, question:"¿Cuáles son las fases habituales que componen un proceso de selección completo para un puesto de desarrollo de software?", options:["Una sola llamada telefónica de 5 minutos","1. Filtro inicial de CV/ATS, 2. Criba telefónica con RRHH (Screening call), 3. Prueba técnica (Take-home o Live coding), 4. Entrevista técnica con el equipo y 5. Entrevista cultural/final y oferta económica","Un examen de mecanografía y firma de contrato","Prueba médica y sorteo"], correct:1, explanation:"Cada fase evalúa aspectos distintos: encaje general, competencias técnicas reales y adecuación cultural al equipo.", noShuffle:false },
  { concept_id:"ipe_u3_q2", unit:3, question:"¿Qué es una 'Prueba Técnica Take-Home' (Proyecto para casa)?", options:["Llevarse los ordenadores de la oficina a casa","Un ejercicio de programación práctico y acotado (ej: construir una pequeña API REST o un componente frontend) que el candidato desarrolla en su entorno local durante unos días para evaluar su código real","Un examen teórico tipo test","Un trabajo sin remuneración de 3 meses"], correct:1, explanation:"Permite al candidato trabajar sin los nervios del directo con sus propias herramientas habituales.", noShuffle:false },
  { concept_id:"ipe_u3_q3", unit:3, question:"¿Qué es el 'Live Coding' o programación en directo durante una entrevista técnica?", options:["Un concierto de música con código","Una sesión en tiempo real (compartiendo pantalla o en una pizarra) donde el candidato resuelve un reto algorítmico o de programación mientras los entrevistadores observan su forma de pensar y razonar","Escribir código sin mirar la pantalla","Un examen a oscuras"], correct:1, explanation:"Más que la solución perfecta memorizada, los evaluadores buscan ver cómo descompones el problema, manejas la frustración y te comunicas.", noShuffle:false },
  { concept_id:"ipe_u3_q4", unit:3, question:"¿Cuál es el consejo fundamental que debe aplicar un candidato durante una prueba de 'Live Coding'?", options:["Permanecer en silencio absoluto hasta terminar","Pensar en voz alta de forma continua explicando tu razonamiento, haciendo preguntas para clarificar requisitos ambiguos y verbalizando alternativas antes de escribir código","Escribir muy rápido sin explicar nada","Rendirse si no se sabe la sintaxis exacta de memoria"], correct:1, explanation:"El entrevistador no puede leer tu mente: pensar en voz alta demuestra estructuración mental y capacidad de colaboración en equipo.", noShuffle:false },
  { concept_id:"ipe_u3_q5", unit:3, question:"¿Qué evalúa la plataforma LeetCode, HackerRank o Codewars en los procesos de selección de gigantes tecnológicos?", options:["La velocidad al teclear","Estructuras de datos (arrays, árboles, grafos, colas), algoritmia y complejidad temporal y espacial (notación Big-O) en problemas lógicos estandarizados","Diseño gráfico con CSS","Redacción de correos comerciales"], correct:1, explanation:"Evalúa fundamentos de ciencias de la computación independientemente del lenguaje específico utilizado.", noShuffle:false },
  { concept_id:"ipe_u3_q6", unit:3, question:"¿Qué es el método 'STAR' para responder con éxito a preguntas de comportamiento (Behavioral Questions) en entrevistas de trabajo?", options:["Un horóscopo de selección","Una técnica estructurada en cuatro pasos: Situación (contexto previo), Tarea (reto u objetivo asignado), Acción (qué hiciste tú concretamente) y Resultado (impacto medible obtenido)","Sencillo, Tranquilo, Amable y Rápido","Un software de recursos humanos"], correct:1, explanation:"Evita respuestas vagas y teóricas aportando ejemplos concretos y comprobables de tu conducta laboral pasada.", noShuffle:false },
  { concept_id:"ipe_u3_q7", unit:3, question:"Ante la típica pregunta en una entrevista: '¿Cuál es tu mayor debilidad o defecto?', ¿cuál es la mejor estrategia de respuesta profesional?", options:["Decir 'Soy demasiado perfeccionista y trabajo demasiado' (cliché poco creíble)","Mencionar una debilidad técnica o profesional real y honesta pero no inhabilitante para el puesto, explicando de inmediato las acciones concretas que estás implementando activamente para superarla","Decir 'No tengo ningún defecto, lo sé todo'","Confesar que te cuesta llegar puntual al trabajo"], correct:1, explanation:"Demuestra autoconciencia madura, honestidad y mentalidad de crecimiento y superación continua.", noShuffle:false },
  { concept_id:"ipe_u3_q8", unit:3, question:"¿Qué es una 'Dinámica de Grupo' (Assessment Center) en un proceso de selección corporativo?", options:["Hacer gimnasia en equipo","Una prueba colectiva donde varios candidatos interactúan para debatir, consensuar y resolver un caso práctico simulado de negocio bajo la atenta observación de psicólogos y reclutadores","Un examen individual de preguntas cerradas","Una fiesta de bienvenida"], correct:1, explanation:"Evalúa habilidades blandas en directo: liderazgo, escucha activa, capacidad de negociación, empatía y trabajo bajo presión.", noShuffle:false },
  { concept_id:"ipe_u3_q9", unit:3, question:"¿Qué papel juegan las 'Soft Skills' (Habilidades Blandas) en la decisión final de contratación de un programador?", options:["No tienen ninguna importancia frente al código","Son decisivas: un perfil técnico brillante con mala comunicación, arrogancia o incapaz de trabajar en equipo suele ser descartado frente a un candidato con buena actitud, humildad y excelentes dotes colaborativas","Solo sirven para puestos directivos","Se aprenden en 10 minutos"], correct:1, explanation:"'Contrata por actitud, entrena la técnica': es mucho más fácil enseñar una tecnología que cambiar una personalidad tóxica en el equipo.", noShuffle:false },
  { concept_id:"ipe_u3_q10", unit:3, question:"¿Qué es la 'Prueba Cultural' o de Ajuste Cultural (Culture Fit / Culture Add)?", options:["Un examen sobre historia y arte de España","Una entrevista diseñada para evaluar si los valores personales, estilo de comunicación, ética y visión del candidato están alineados con la cultura y forma de trabajar del equipo de la empresa","Un test de idiomas extranjeros","Una prueba médica"], correct:1, explanation:"Busca asegurar una convivencia armónica y que el nuevo miembro sume diversidad de pensamiento positiva al grupo.", noShuffle:false },
  { concept_id:"ipe_u3_q11", unit:3, question:"Cuando al final de una entrevista te preguntan: '¿Tienes alguna pregunta para nosotros?', ¿por qué NUNCA debes responder 'No, ninguna'?", options:["Porque es de mala educación levantarse rápido","Porque demuestra falta de interés y proactividad; hacer preguntas inteligentes sobre el stack técnico, metodología ágil, retos del equipo o cultura demuestra que tú también estás evaluando si la empresa es el lugar adecuado para ti","Porque es obligatorio preguntar el sueldo del director","Porque se suspende la entrevista de inmediato"], correct:1, explanation:"Una entrevista es una conversación bidireccional entre profesionales y no un interrogatorio policial pasivo.", noShuffle:false },
  { concept_id:"ipe_u3_q12", unit:3, question:"¿Cuál de las siguientes es una excelente pregunta para formular al equipo técnico durante la entrevista?", options:["¿A qué hora nos podemos marchar los viernes sin que nos vean?","¿Cómo gestionáis la deuda técnica en el día a día y qué cobertura de tests automatizados tenéis en vuestro pipeline de CI/CD?","¿Por qué despidieron al anterior programador?","¿Puedo trabajar sin encender la cámara nunca?"], correct:1, explanation:"Evidencia un criterio de ingeniería profesional maduro y conocimiento de las mejores prácticas de la industria.", noShuffle:false },
  { concept_id:"ipe_u3_q13", unit:3, question:"¿Qué es el 'Salario Bruto' frente al 'Salario Neto' que debes negociar al recibir una oferta laboral?", options:["Son sinónimos en las nóminas","El Salario Bruto es la cantidad total pactada antes de aplicar las retenciones de IRPF y cotizaciones a la Seguridad Social; el Salario Neto es el dinero líquido real que el trabajador ingresa efectivamente en su cuenta bancaria cada mes","El salario neto incluye los impuestos","El salario bruto solo se cobra en Navidad"], correct:1, explanation:"Las empresas siempre contratan y negocian en Salario Bruto Anual (SBA), ya que el neto varía según las circunstancias personales fiscales de cada trabajador.", noShuffle:false },
  { concept_id:"ipe_u3_q14", unit:3, question:"¿Qué es el 'Salario en Especie' o Retribución Flexible en una oferta de trabajo?", options:["Pagar el salario con especias de cocina","Beneficios no dinerarios que la empresa ofrece al trabajador como parte de su retribución con ventajas fiscales (ej: seguro médico privado, tickets restaurante, tarjeta transporte, guardería) hasta un límite legal del 30% del salario","Cobrar con productos defectuosos","Un bono anual extraordinario"], correct:1, explanation:"Reduce la base imponible del IRPF incrementando el salario neto disponible del empleado a final de mes.", noShuffle:false },
  { concept_id:"ipe_u3_q15", unit:3, question:"¿Qué es la 'Cláusula de Confidencialidad' (NDA - Non-Disclosure Agreement) que se firma al inicio de un proceso de selección o contrato?", options:["Un acuerdo para no hablar con los compañeros","Un compromiso legal vinculante que prohíbe revelar información confidencial, código fuente propietario, secretos comerciales o datos de clientes a los que tengas acceso durante la relación laboral","Un contrato de exclusividad obligatoria","Un permiso para usar marcas"], correct:1, explanation:"El incumplimiento de un acuerdo de confidencialidad acarrea graves responsabilidades civiles y penales.", noShuffle:false },
  { concept_id:"ipe_u3_q16", unit:3, question:"¿Qué es una 'Prueba de Arquitectura y Diseño de Sistemas' (System Design Interview)?", options:["Diseñar planos de casas con arquitectos","Una entrevista técnica para evaluar cómo diseñarías una arquitectura de software escalable, fiable y tolerante a fallos para un problema masivo (ej: '¿Cómo diseñarías el sistema de mensajería de WhatsApp o la API de Twitter?')","Un examen de dibujo en papel","Una prueba de formateo de ordenadores"], correct:1, explanation:"Evalúa cómo seleccionas bases de datos (SQL vs NoSQL), balanceadores de carga, cachés (Redis), microservicios y particionado de datos.", noShuffle:false },
  { concept_id:"ipe_u3_q17", unit:3, question:"¿Qué es la 'Negociación Salarial Basada en Valor'?", options:["Exigir el sueldo más alto gritando","Argumentar tu petición salarial basándote en datos empíricos de mercado (tablas salariales del sector) y en el valor medible y competencias tangibles que aportarás al negocio, en lugar de en necesidades personales privadas","Aceptar la primera cifra que te ofrezcan sin dudar","Pedir aumentos de sueldo cada semana"], correct:1, explanation:"La negociación exitosa es colaborativa: demuestra que contratarte por ese importe es una inversión rentable para la empresa.", noShuffle:false },
  { concept_id:"ipe_u3_q18", unit:3, question:"¿Qué es una 'Carta de Oferta' (Offer Letter) formal?", options:["Un folleto publicitario","Un documento formal emitido por la empresa que detalla la propuesta laboral en firme: puesto, salario bruto anual, beneficios, fecha de inicio prevista, horario y periodo de prueba antes de la firma del contrato definitivo","Un recibo bancario","La carta de despido"], correct:1, explanation:"Permite al candidato revisar todas las condiciones pactadas por escrito antes de renunciar a su puesto de trabajo anterior.", noShuffle:false },
  { concept_id:"ipe_u3_q19", unit:3, question:"¿Qué significa el 'Periodo de Prueba' en un contrato laboral y qué implicaciones tiene?", options:["Un tiempo en el que no se cobra salario","Un periodo inicial acordado por escrito durante el cual tanto el trabajador como la empresa pueden rescindir el contrato unilateralmente en cualquier momento sin necesidad de alegar causa, sin preaviso y sin derecho a indemnización","Un curso de formación obligatorio","Un examen médico periódico"], correct:1, explanation:"Durante el periodo de prueba el trabajador cobra el 100% de su salario y genera cotizaciones a la Seguridad Social.", noShuffle:false },
  { concept_id:"ipe_u3_q20", unit:3, question:"¿Qué duración máxima puede tener el periodo de prueba para técnicos titulados según el Estatuto de los Trabajadores en España (salvo que el convenio fije otra menor)?", options:["15 días","Hasta 6 meses (para técnicos titulados de grado superior o universitario)","2 años","1 semana únicamente"], correct:1, explanation:"El Estatuto fija hasta 6 meses para técnicos titulados y hasta 2 meses para los demás trabajadores (ampliable o reducible por convenio colectivo).", noShuffle:false },
  { concept_id:"ipe_u3_q21", unit:3, question:"¿Qué es el 'Lenguaje Corporal' (Comunicación No Verbal) en una videollamada de entrevista técnica?", options:["Los gestos de un actor de teatro","La postura erguida, mirar a la lente de la cámara (para simular contacto visual directo), sonreír con naturalidad y evitar distracciones o consultar segundas pantallas mientras te hablan","Apagar la cámara siempre","Hablar muy alto por el micrófono"], correct:1, explanation:"Transmite seguridad, escucha atenta y entusiasmo profesional a través de la pantalla.", noShuffle:false },
  { concept_id:"ipe_u3_q22", unit:3, question:"¿Cómo se debe preparar técnicamente el entorno antes de una entrevista de trabajo por videollamada?", options:["Conectarse dos minutos tarde sin probar nada","Comprobar audio del micrófono, cámara web, iluminación frontal adecuada, fondo neutro y ordenado, conexión estable a internet y cerrar pestañas o notificaciones ruidosas con antelación","Hacer la entrevista en un lugar con música alta","Usar un micrófono que acople sonido"], correct:1, explanation:"Elimina imprevistos técnicos molestos que generan una primera impresión descuidada.", noShuffle:false },
  { concept_id:"ipe_u3_q23", unit:3, question:"¿Qué es una pregunta sobre 'Resolución de Conflictos' en una entrevista técnica de trabajo?", options:["Preguntar si sabes artes marciales","Preguntas como 'Cuéntame una ocasión en la que tuviste un desacuerdo técnico sobre una arquitectura con un compañero y cómo lo resolviste', evaluando madurez, escucha activa y búsqueda de consenso profesional","Una discusión real entre entrevistadores","Un examen de derecho procesal"], correct:1, explanation:"Demuestra que antepones el éxito del proyecto y la armonía del equipo a los egos personales.", noShuffle:false },
  { concept_id:"ipe_u3_q24", unit:3, question:"¿Por qué es fundamental admitir con naturalidad un 'No lo sé, pero sé cómo investigarlo y encontrar la solución' ante una pregunta técnica desconocida en la entrevista?", options:["Porque demuestra ignorancia","Porque los evaluadores a menudo preguntan conceptos avanzados a propósito para medir tu honestidad intelectual y tu capacidad de resolución ante la incertidumbre; inventarse una respuesta falsa es motivo de descarte inmediato","Porque la entrevista se termina ahí","Para que te cambien de pregunta"], correct:1, explanation:"En desarrollo de software la humildad y la destreza de búsqueda superan con creces a la falsa arrogancia.", noShuffle:false },
  { concept_id:"ipe_u3_q25", unit:3, question:"¿Qué es el 'Email de Agradecimiento' tras finalizar una entrevista de trabajo?", options:["Un correo de spam automático","Un correo breve y educado enviado dentro de las 24 horas siguientes a los entrevistadores agradeciendo su tiempo, reiterando tu entusiasmo por el proyecto y recordando brevemente un punto de conexión positivo tratado en la sesión","Un mensaje exigiendo una respuesta inmediata","Una queja sobre las preguntas formuladas"], correct:1, explanation:"Refuerza una impresión profesional madura y te mantiene presente en la mente de los decisores.", noShuffle:false },
  { concept_id:"ipe_u3_q26", unit:3, question:"¿Qué es una 'Red Flag' (Señal de Alerta) para el candidato durante un proceso de selección en una empresa?", options:["Una bandera roja decorativa en la recepción","Indicios de mala gestión o toxicidad: alta rotación injustificada, entrevistadores arrogantes o despectivos, descripciones de puesto caóticas, exigencia de disponibilidad permanente fuera de horario o rechazo a hablar de rangos salariales transparentes","Tener ordenadores nuevos en la oficina","Que te hagan muchas preguntas técnicas"], correct:1, explanation:"Permite al candidato descartar ofertas en empresas que perjudicarían su salud mental y crecimiento profesional.", noShuffle:false },
  { concept_id:"ipe_u3_q27", unit:3, question:"¿Qué es un 'Caso Práctico' (Business Case) en un proceso de selección?", options:["Un maletín de cuero para trabajar","La presentación de un problema o reto real que afrontó la empresa para que el candidato plantee cómo lo abordaría, qué preguntas formularía y qué arquitectura técnica propondría","Un juicio legal simulado","Una prueba de velocidad en teclado"], correct:1, explanation:"Evalúa pensamiento estratégico, visión de negocio y aplicabilidad práctica de las tecnologías.", noShuffle:false },
  { concept_id:"ipe_u3_q28", unit:3, question:"¿Qué significa el término 'Feedback Técnico' que se debe solicitar tras una prueba de código?", options:["Pedir dinero por el ejercicio realizado","La retroalimentación crítica constructiva de los evaluadores sobre qué aspectos de tu código valoraron positivamente y qué áreas de mejora identificaron (arquitectura, tests, modularidad, rendimiento)","Una queja formal al ministerio","Un certificado de asistencia"], correct:1, explanation:"Convierte cualquier proceso de selección, incluso los no superados, en una oportunidad impagable de aprendizaje acelerado.", noShuffle:false },
  { concept_id:"ipe_u3_q29", unit:3, question:"¿Qué es una entrevista 'Asíncrona' por vídeo (One-Way Video Interview)?", options:["Una videollamada sin conexión a internet","Un proceso donde una plataforma graba las respuestas en vídeo del candidato a preguntas predeterminadas mostradas en pantalla con un tiempo límite, sin presencia de un entrevistador humano en directo","Un mensaje de voz de WhatsApp","Una película de cine"], correct:1, explanation:"Utilizada en cribas masivas iniciales; exige mirar fijamente a la cámara y estructurar las respuestas en el tiempo pautado.", noShuffle:false },
  { concept_id:"ipe_u3_q30", unit:3, question:"¿Qué papel desempeña la 'Puntualidad Absoluta' en las citas de entrevistas técnicas?", options:["No tiene ninguna importancia en el sector informal de TI","Es un indicador crítico no negociable de respeto, formalidad, rigor y compromiso; llegar tarde sin aviso previo suele suponer la descalificación inmediata del candidato","Se puede llegar 20 minutos tarde con normalidad","La puntualidad es opcional"], correct:1, explanation:"Estar conectado y listo 5 minutos antes demuestra seriedad y respeto por la agenda del equipo.", noShuffle:false },
  { concept_id:"ipe_u3_q31", unit:3, question:"¿Qué es la 'Cláusula de No Competencia Postcontractual' en una oferta de trabajo?", options:["Un acuerdo para no competir en videojuegos","Un pacto contractual donde el trabajador se compromete a no trabajar para empresas de la competencia directa tras finalizar su contrato durante un tiempo pactado (máximo 2 años para técnicos); solo es válida si la empresa le abona una compensación económica adecuada","Un despido con indemnización","Una multa por trabajar"], correct:1, explanation:"El artículo 21 del Estatuto de los Trabajadores exige interés comercial efectivo y compensación económica expresa para que sea legal.", noShuffle:false },
  { concept_id:"ipe_u3_q32", unit:3, question:"¿Qué es el 'Benchmarking Salarial' para preparar una negociación?", options:["Un software para probar la tarjeta gráfica","Investigar y conocer los rangos salariales reales del mercado para tu puesto específico, nivel de experiencia y ubicación geográfica mediante informes del sector (ej: Guía Salarial Hays, Michael Page, Manfred, Glassdoor)","Adivinar cuánto dinero gana el director","Preguntar el sueldo a un amigo al azar"], correct:1, explanation:"Evita pedir cifras irrisorias que te desvaloricen o cifras desorbitadas fuera de la realidad de mercado.", noShuffle:false },
  { concept_id:"ipe_u3_q33", unit:3, question:"¿Por qué se deben preparar preguntas sobre 'Resolución de Bugs en Producción' en entrevistas técnicas?", options:["Para saber si eres hacker","Porque en el trabajo real las cosas fallan: quieren saber cómo mantienes la calma, cómo aíslas el fallo con logs y tests, cómo aplicas un rollback o hotfix y cómo redactas un Post-Mortem sin culpar a personas (Blameless Post-Mortem)","Porque los programadores junior rompen las cosas a propósito","Para comprobar si sabes formatear ordenadores"], correct:1, explanation:"El manejo sereno y sistemático de incidentes críticos es la marca de un profesional maduro.", noShuffle:false },
  { concept_id:"ipe_u3_q34", unit:3, question:"¿Qué es un 'Code Review Simulada' en una entrevista técnica avanzada?", options:["Corregir faltas de ortografía en un texto","Un ejercicio donde el entrevistador te entrega un fragmento de código con malas prácticas intencionadas, fallos de seguridad o bugs de rendimiento para que lo revises y emitas comentarios constructivos como harías en un Pull Request real","Un examen de mecanografía","Un compilador de código en vivo"], correct:1, explanation:"Evalúa tu ojo crítico para la calidad de software y tu capacidad para comunicarte con empatía pedagógica con tus compañeros.", noShuffle:false },
  { concept_id:"ipe_u3_q35", unit:3, question:"¿Qué es la 'Firma Digital de la Oferta de Empleo' mediante plataformas como DocuSign o Signaturit?", options:["Dibujar tu nombre en Paint","Un proceso legal y seguro que utiliza certificados digitales o firmas electrónicas avanzadas para formalizar la aceptación de la oferta de trabajo desde cualquier lugar con plena validez jurídica","Un escaneo de un papel firmado","Un mensaje de texto de confirmación"], correct:1, explanation:"Estandariza los procesos de contratación en empresas remotas y multinacionales sin necesidad de desplazamientos físicos.", noShuffle:false },
  { concept_id:"ipe_u3_q36", unit:3, question:"¿Qué significa el término 'Onboarding Técnico' que comienza tras superar el proceso de selección?", options:["Subirse a un avión corporativo","El periodo estructurado de acogida e integración donde la empresa entrega el equipamiento, accesos a repositorios y credenciales, asigna un 'Buddy' (mentor compañero) y guía al nuevo empleado para desplegar su primer commit en producción de forma acompañada","Un examen de reválida laboral","El pago de la primera nómina"], correct:1, explanation:"Un onboarding técnico excelente reduce a la mitad el tiempo necesario para que un nuevo programador sea plenamente productivo y autónomo.", noShuffle:false },
  { concept_id:"ipe_u3_q37", unit:3, question:"¿Cómo se debe explicar en una entrevista un proyecto personal que fracasó o no llegó a publicarse?", options:["Ocultarlo y no mencionarlo jamás","Con orgullo y madurez: explicando qué intentaste construir, por qué no funcionó como esperabas (problemas técnicos o de mercado), qué aprendiste de los errores y cómo aplicarías esas lecciones hoy para tener éxito","Echarle la culpa a los compañeros de equipo","Decir que el mercado no estaba preparado para tu genialidad"], correct:1, explanation:"Los líderes técnicos valoran profundamente a los profesionales que asumen sus fallos con humildad y extraen aprendizajes sólidos.", noShuffle:false },
  { concept_id:"ipe_u3_q38", unit:3, question:"¿Qué es el 'Parálisis por Análisis' al abordar un reto de código en una entrevista técnica?", options:["Un problema muscular real","Quedarse bloqueado intentando diseñar la solución teórica perfecta y definitiva en la cabeza sin escribir una sola línea de código; se supera escribiendo primero una solución básica directa ('fuerza bruta') que funcione y optimizándola después","Un fallo de la pantalla del ordenador","Un error de sintaxis en el compilador"], correct:1, explanation:"'Make it work, make it right, make it fast': primero haz que funcione, luego hazlo elegante y luego hazlo rápido.", noShuffle:false },
  { concept_id:"ipe_u3_q39", unit:3, question:"¿Qué importancia tiene la 'Modularidad y Legibilidad' del código en una prueba técnica frente a resolverla en una sola línea ilegible de código (One-liner)?", options:["Las líneas cortas son mejores siempre","El código limpio, con nombres de variables descriptivos, funciones pequeñas de responsabilidad única y buenas prácticas es inmensamente más valorado que una línea críptica incomprensible de código 'hacker'","La legibilidad no importa si funciona","Solo importa el tiempo de ejecución"], correct:1, explanation:"El código se escribe una vez pero se lee y mantiene cientos de veces por otros compañeros de equipo.", noShuffle:false },
  { concept_id:"ipe_u3_q40", unit:3, question:"¿Qué es el 'Preaviso' legal al dimitir voluntariamente de una empresa en España para cambiar de trabajo?", options:["Avisar un año antes","La comunicación formal y por escrito a la empresa con el tiempo de antelación que fije el convenio colectivo del sector (habitualmente 15 días naturales); de no cumplirse, la empresa puede descontar los días de falta de preaviso de la liquidación final","Marcharse de la oficina sin decir nada","Un permiso de vacaciones retribuidas"], correct:1, explanation:"Cumplir rigurosamente el preaviso preserva tu reputación profesional y garantiza el cobro íntegro del finiquito devengado.", noShuffle:false },
  { concept_id:"ipe_u3_q41", unit:3, question:"¿Por qué nunca se debe hablar mal de tus anteriores jefes, profesores o compañeros durante una entrevista de trabajo?", options:["Porque pueden demandarte por difamación","Porque proyecta inmediatamente una imagen de persona conflictiva, rencorosa y desleal que genera rechazo instantáneo en los evaluadores","Porque los entrevistadores conocen a todos los jefes del mundo","Porque es obligatorio alabar a todas las empresas"], correct:1, explanation:"Enfoca siempre el relato en tu deseo de afrontar nuevos retos y crecer profesionalmente, manteniendo un tono constructivo y elegante.", noShuffle:false },
  { concept_id:"ipe_u3_q42", unit:3, question:"¿Cuál es la mentalidad idónea para afrontar los procesos de selección en el sector del desarrollo web?", options:["Considerar la entrevista como una batalla o examen intimidatorio donde intentan pillarte","Ver el proceso como una reunión colaborativa entre iguales donde ambas partes exploran si existe una alianza profesional beneficiosa mutua, demostrando pasión por la ingeniería y ganas sinceras de aportar valor","Memorizar todas las respuestas de memoria sin entenderlas","Aceptar cualquier oferta por mala que sea sin evaluar a la empresa"], correct:1, explanation:"La seguridad profesional nace de tus proyectos reales y de tu compromiso continuo con la excelencia técnica y humana.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 4 — Contratos, Relaciones Laborales y Seguridad Social
  // ════════════════════════════════════════════════════════════════
  { concept_id:"ipe_u4_q1", unit:4, question:"¿Cuál es la norma jurídica suprema que regula las relaciones laborales individuales y colectivas entre trabajadores y empresarios en España?", options:["El Código Civil","El Estatuto de los Trabajadores (Real Decreto Legislativo 2/2015)","La Ley de Sociedades de Capital","El Código de Comercio"], correct:1, explanation:"El Estatuto de los Trabajadores fija los derechos mínimos e indisponibles que ningún contrato individual ni convenio colectivo puede empeorar.", noShuffle:false },
  { concept_id:"ipe_u4_q2", unit:4, question:"¿Cuál es la regla contractual general en España tras la reforma laboral del Real Decreto-ley 32/2021?", options:["El contrato temporal por obra y servicio","El contrato de trabajo se presume concertado por tiempo indefinido (contrato fijo e indefinido como norma general)","El contrato de prueba gratuito","El contrato por horas"], correct:1, explanation:"La reforma laboral eliminó el contrato por obra o servicio determinado, restringiendo la temporalidad a causas muy tasadas y excepcionales.", noShuffle:false },
  { concept_id:"ipe_u4_q3", unit:4, question:"¿Cuáles son las dos únicas modalidades legales de contrato temporal que contempla la legislación laboral española actual?", options:["Contrato verbal y contrato escrito","Por circunstancias de la producción (incrementos ocasionales imprevisibles u oscilaciones de demanda) y por sustitución de persona trabajadora (con derecho a reserva de puesto)","Contrato temporal de prueba y contrato eventual libre","Contrato temporal por horas"], correct:1, explanation:"Cualquier contratación temporal que no justifique expresamente estas causas rigurosas se considera celebrada en fraude de ley y pasa a fija indefinida.", noShuffle:false },
  { concept_id:"ipe_u4_q4", unit:4, question:"¿Qué es el 'Contrato Formativo para la Obtención de la Práctica Profesional' adecuado para recién graduados de FP?", options:["Prácticas extracurriculares sin remuneración","Un contrato laboral retribuido concertado con quienes estén en posesión de un título de FP o grado universitario dentro de los 3 años siguientes a su obtención, con una duración de entre 6 meses y 1 año","Un contrato de voluntariado","Un contrato de autónomo dependiente"], correct:1, explanation:"Proporciona práctica profesional remunerada adecuada al nivel de estudios cursado con cotizaciones completas a la Seguridad Social.", noShuffle:false },
  { concept_id:"ipe_u4_q5", unit:4, question:"¿Qué es un 'Convenio Colectivo' y cuál aplica habitualmente a los desarrolladores de software en empresas de consultoría en España?", options:["Un acuerdo informal entre amigos","Una norma jurídica vinculante negociada entre representantes de los trabajadores y patronales empresariales que regula condiciones laborales y salariales mínimas del sector (ej: Convenio Colectivo Estatal de Empresas de Consultoría, Tecnologías de la Información y Estudios de Mercado)","Una ley aprobada por el Congreso","El contrato individual firmado"], correct:1, explanation:"El convenio del sector TIC establece tablas salariales mínimas obligatorias por categorías profesionales (trienios, pluses, guardias, jornadas).", noShuffle:false },
  { concept_id:"ipe_u4_q6", unit:4, question:"¿Qué significa el 'Principio de Norma Más Favorable' en el Derecho Laboral español?", options:["Que siempre se aplica la ley del país más rico","En caso de conflicto o concurrencia entre dos o más normas laborales aplicables a un caso, se aplicará aquella que resulte más favorable para el trabajador apreciada en su conjunto","Que el empresario elige la norma que prefiera","Que se aplica la norma más corta"], correct:1, explanation:"Garantiza la protección del trabajador como la parte contractualmente más débil de la relación laboral.", noShuffle:false },
  { concept_id:"ipe_u4_q7", unit:4, question:"¿Qué significa el 'Principio de Condición Más Beneficiosa'?", options:["Pagar siempre en efectivo","Si un trabajador pacta en su contrato individual o recibe voluntariamente del empresario una condición más ventajosa que la fijada en el convenio (ej: más días de vacaciones o mayor sueldo), esta condición se mantiene y no puede ser retirada unilateralmente","Tener el mejor despacho de la empresa","Un descuento en el supermercado"], correct:1, explanation:"Los derechos adquiridos a título individual se consolidan y protegen frente a empeoramientos colectivos.", noShuffle:false },
  { concept_id:"ipe_u4_q8", unit:4, question:"¿Cuál es la duración máxima ordinaria de la jornada laboral legal establecida por el Estatuto de los Trabajadores en España?", options:["48 horas semanales","40 horas semanales de trabajo efectivo de promedio en cómputo anual (con un máximo diario ordinario de 9 horas de trabajo)","30 horas semanales","50 horas semanales"], correct:1, explanation:"Entre el final de una jornada y el comienzo de la siguiente deben mediar como mínimo 12 horas de descanso ininterrumpido.", noShuffle:false },
  { concept_id:"ipe_u4_q9", unit:4, question:"¿Cuál es la retribución o compensación mínima exigida para las 'Horas Extraordinarias' según la legislación laboral?", options:["Se pagan obligatoriamente al doble del salario habitual","No pueden retribuirse por debajo del valor de la hora ordinaria de trabajo o bien compensarse con descansos retribuidos equivalentes dentro de los 4 meses siguientes a su realización","Son gratuitas por ley","Se compensan con días libres sin sueldo"], correct:1, explanation:"El Estatuto prohíbe realizar más de 80 horas extraordinarias al año (salvo las de fuerza mayor para reparar siniestros).", noShuffle:false },
  { concept_id:"ipe_u4_q10", unit:4, question:"¿Qué es el 'Registro Diario de Jornada' obligatorio para todas las empresas en España desde el Real Decreto-ley 8/2019?", options:["Un libro de quejas diario","La obligación legal de la empresa de registrar diariamente el horario concreto de inicio y finalización de la jornada laboral de cada trabajador para controlar excesos de jornada y horas extras no pagadas","Un control biométrico obligatorio","Un informe de tareas realizadas"], correct:1, explanation:"Debe conservarse durante 4 años y estar permanentemente a disposición de los trabajadores, sus representantes y la Inspección de Trabajo.", noShuffle:false },
  { concept_id:"ipe_u4_q11", unit:4, question:"¿Cuántos días de 'Vacaciones Retribuidas' anuales garantiza como mínimo irrenunciable el Estatuto de los Trabajadores?", options:["15 días naturales","30 días naturales (o 22 días laborables) por cada año de trabajo efectivo, no sustituibles por compensación económica salvo extinción de contrato","45 días naturales","20 días laborables únicamente"], correct:1, explanation:"Las vacaciones no se pueden pagar con dinero; el trabajador tiene el derecho irrenunciable a disfrutarlas en tiempo de descanso efectivo.", noShuffle:false },
  { concept_id:"ipe_u4_q12", unit:4, question:"¿Qué ley regula específicamente el 'Trabajo a Distancia' y Teletrabajo en España (Ley 10/2021)?", options:["La Ley de Seguridad Social","La Ley 10/2021 que establece que el teletrabajo debe ser voluntario, reversible, formalizado por escrito mediante acuerdo individual y que los gastos de equipamiento, herramientas y consumibles deben ser sufragados por la empresa sin coste para el empleado","El Código de Comercio","Una directiva de tráfico"], correct:1, explanation:"Se considera trabajo a distancia regular cuando se presta al menos el 30% de la jornada en un periodo de referencia de 3 meses en remoto.", noShuffle:false },
  { concept_id:"ipe_u4_q13", unit:4, question:"¿Cuáles son las dos partes principales en las que se divide formalmente el documento de una 'Nómina' (Recibo de Salarios)?", options:["Preguntas y respuestas","Devengos (percepciones salariales y no salariales que componen el Salario Bruto) y Deducciones (aportaciones del trabajador a la Seguridad Social y retenciones del IRPF que dan como resultado el Líquido a Percibir)","Entrada y salida","Débito y crédito bancario"], correct:1, explanation:"Devengos - Deducciones = Líquido a percibir (el salario neto que llega a la cuenta bancaria).", noShuffle:false },
  { concept_id:"ipe_u4_q14", unit:4, question:"¿Qué conceptos de cotización a la Seguridad Social se deducen mensualmente de la nómina del trabajador?", options:["Solo la jubilación","Contingencias Comunes (enfermedad común/accidente no laboral y jubilación: 4.70%), Desempleo (1.55% o 1.60%), Formación Profesional (0.10%) y Mecanismo de Equidad Intergeneracional (MEI)","El IVA del sueldo","El seguro del edificio"], correct:1, explanation:"Estas cotizaciones otorgan el derecho a la pensión de jubilación, prestaciones por incapacidad temporal y prestación por desempleo (paro).", noShuffle:false },
  { concept_id:"ipe_u4_q15", unit:4, question:"¿Qué es el 'IRPF' (Impuesto sobre la Renta de las Personas Físicas) retenido en la nómina?", options:["Una tasa municipal del ayuntamiento","Un pago a cuenta adelantado mensual que la empresa retiene del sueldo y transfiere a la Agencia Tributaria en nombre del trabajador en función de su escala de ingresos anuales y circunstancias familiares","Una cotización para pensiones","Un fondo de ahorro privado"], correct:1, explanation:"Al hacer la Declaración de la Renta anual se ajusta si las retenciones practicadas fueron mayores (sale a devolver) o menores (sale a pagar).", noShuffle:false },
  { concept_id:"ipe_u4_q16", unit:4, question:"¿Qué son las 'Gratificaciones Extraordinarias' (Pagas Extras) en la legislación laboral española?", options:["Propinas voluntarias del jefe","Dos pagas adicionales al año que el trabajador tiene derecho a percibir (habitualmente una en Navidad y otra fijada por convenio en verano); pueden cobrarse en esos meses o prorratearse en las 12 mensualidades ordinarias","Bonos por objetivos excepcionales","Pagas que solo cobran los funcionarios"], correct:1, explanation:"El Salario Bruto Anual pactado es exactamente el mismo tanto si se cobra en 12 pagas prorrateadas como en 14 pagas.", noShuffle:false },
  { concept_id:"ipe_u4_q17", unit:4, question:"¿Cuál es la diferencia entre el Régimen General y el RETA en el sistema de la Seguridad Social española?", options:["No hay diferencia","El Régimen General encuadra a los trabajadores por cuenta ajena contratados por una empresa; el RETA (Régimen Especial de Trabajadores Autónomos) encuadra a quienes realizan una actividad económica por cuenta propia de forma habitual y directa","El RETA es para funcionarios","El Régimen General no tiene desempleo"], correct:1, explanation:"Ambos regímenes ofrecen coberturas asistenciales pero con mecanismos de cotización y gestión diferenciados.", noShuffle:false },
  { concept_id:"ipe_u4_q18", unit:4, question:"¿Qué es una Incapacidad Temporal (IT) comúnmente conocida como 'Baja Médica'?", options:["Un despido temporal","La situación en la que un trabajador está impedido para el trabajo por enfermedad común, accidente no laboral, accidente de trabajo o enfermedad profesional y recibe asistencia sanitaria de la Seguridad Social y un subsidio económico sustitutivo","Un permiso retribuido de vacaciones","Una falta injustificada al puesto"], correct:1, explanation:"Expedida exclusivamente por un médico del servicio público de salud o mutua colaboradora con partes oficiales de confirmación.", noShuffle:false },
  { concept_id:"ipe_u4_q19", unit:4, question:"¿Qué es el 'Finiquito' (Documento de Liquidación) al extinguirse una relación laboral?", options:["Una carta de despido únicamente","El documento que liquida todas las cantidades económicas pendientes de abono entre empresa y trabajador en el momento del cese: días de sueldo del mes en curso, parte proporcional de pagas extras devengadas y no cobradas y vacaciones generadas y no disfrutadas","La indemnización por despido exclusivamente","El certificado de empresa para el paro"], correct:1, explanation:"Debe liquidarse siempre independientemente de cuál haya sido la causa del fin del contrato (dimisión voluntaria, despido o fin de contrato temporal).", noShuffle:false },
  { concept_id:"ipe_u4_q20", unit:4, question:"¿Cuál es la diferencia legal entre 'Finiquito' e 'Indemnización' por despido?", options:["Son exactamente lo mismo","El finiquito salda deudas salariales pendientes que el trabajador ya se ha ganado trabajando (vacaciones, pagas extras, días trabajados); la indemnización es una compensación económica adicional que la ley exige pagar al trabajador cuando el despido no es imputable a una falta disciplinaria propia","El finiquito solo se paga en despidos nulos","La indemnización es voluntaria"], correct:1, explanation:"Si un trabajador dimite voluntariamente, tiene derecho a finiquito pero NO a indemnización.", noShuffle:false },
  { concept_id:"ipe_u4_q21", unit:4, question:"¿Cuáles son las causas y la indemnización legal por un 'Despido Objetivo' (económico, técnico, organizativo o de producción) procedente en España?", options:["Cero euros de indemnización","Causas económicas justificadas (pérdidas persistentes), técnicas o productivas; la indemnización legal es de 20 días de salario por año trabajado con un máximo de 12 mensualidades y 15 días de preaviso por escrito","45 días de salario por año trabajado","El sueldo de un mes completo"], correct:1, explanation:"Debe comunicarse mediante carta motivada detallando los hechos económicos que justifican la decisión extintiva.", noShuffle:false },
  { concept_id:"ipe_u4_q22", unit:4, question:"¿Qué es un 'Despido Disciplinario' y qué indemnización económica conlleva si es declarado procedente?", options:["Conlleva 33 días de salario por año","El motivado por un incumplimiento contractual grave y culpable del trabajador (faltas repetidas de asistencia, indisciplina, ofensas verbales, embriaguez habitual o transgresión de la buena fe contractual); si es procedente conlleva CERO días de indemnización","Conlleva el pago de 12 meses de sueldo","Conlleva una pensión vitalicia"], correct:1, explanation:"El trabajador despedido disciplinariamente no cobra indemnización pero SÍ cobra su finiquito devengado y tiene derecho a cobrar la prestación por desempleo.", noShuffle:false },
  { concept_id:"ipe_u4_q23", unit:4, question:"¿Qué ocurre legalmente si un despido es impugnado en los juzgados de lo social y el juez lo califica como 'Despido Improcedente'?", options:["El juez mete al empresario en la cárcel","El empresario debe optar en el plazo de 5 días entre readmitir al trabajador abonando los salarios de tramitación o pagarle una indemnización de 33 días de salario por año trabajado con un máximo de 24 mensualidades","El contrato se renueva por 10 años","El trabajador no puede cobrar el paro"], correct:1, explanation:"Para contratos anteriores a febrero de 2012 se aplica el tramo de 45 días por año hasta un tope de 42 mensualidades.", noShuffle:false },
  { concept_id:"ipe_u4_q24", unit:4, question:"¿Cuándo es calificado un despido judicialmente como 'Despido Nulo' en España?", options:["Cuando la empresa no tiene dinero","Cuando el despido tiene como móvil alguna de las causas de discriminación prohibidas en la Constitución o se produce con violación de derechos fundamentales (ej: durante embarazo, permiso de maternidad/paternidad o reducción de jornada por cuidado de hijos)","Cuando la carta tiene faltas de ortografía","Cuando el trabajador era junior"], correct:1, explanation:"La declaración de nulidad acarrea la readmisión inmediata obligatoria del trabajador en su puesto con el abono íntegro de todos los salarios de tramitación dejados de percibir.", noShuffle:false },
  { concept_id:"ipe_u4_q25", unit:4, question:"¿Qué son los 'Salarios de Tramitación' en un proceso judicial de despido?", options:["Tasas que se pagan a los juzgados de lo social","Los salarios dejados de percibir por el trabajador desde la fecha del despido hasta la fecha de notificación de la sentencia judicial (o hasta que encontró otro empleo) cuando el despido es declarado nulo o improcedente con readmisión","El coste de los abogados laboralistas","Una ayuda por desempleo"], correct:1, explanation:"Reparan el perjuicio económico sufrido durante los meses que duró el procedimiento judicial de despido nulo.", noShuffle:false },
  { concept_id:"ipe_u4_q26", unit:4, question:"¿Cuál es el plazo estricto y de caducidad para que un trabajador demande a la empresa ante el SMAC y Juzgado de lo Social por disconformidad con un despido?", options:["1 año","20 días hábiles (excluyendo sábados, domingos y festivos) desde el día siguiente a la fecha de efectos del despido","3 meses","15 días naturales"], correct:1, explanation:"Es un plazo perentorio muy breve: si transcurren los 20 días hábiles sin presentar la papeleta de conciliación, la acción de despido caduca definitivamente.", noShuffle:false },
  { concept_id:"ipe_u4_q27", unit:4, question:"¿Qué es la 'Papeleta de Conciliación' y el acto ante el SMAC (Servicio de Mediación, Arbitraje y Conciliación)?", options:["Un examen oficial para conciliar la vida laboral","Un trámite previo obligatorio por ley antes de interponer demanda judicial de despido donde trabajador y empresa se reúnen ante un letrado conciliador para intentar alcanzar un acuerdo indemnizatorio sin juicio","La firma del contrato indefinido","Un trámite fiscal ante la Agencia Tributaria"], correct:1, explanation:"Si hay avenencia (acuerdo), el acta tiene fuerza ejecutiva idéntica a una sentencia judicial; si no hay acuerdo, se abre la vía judicial directa.", noShuffle:false },
  { concept_id:"ipe_u4_q28", unit:4, question:"¿Tiene derecho a cobrar la prestación por desempleo (paro) un trabajador que causa 'Baja Voluntaria' (dimisión) de su puesto de trabajo?", options:["Sí, siempre que haya cotizado 360 días","NO, la ley exige encontrarse en 'situación legal de desempleo' (involuntaria, por despido o fin de contrato temporal); la dimisión voluntaria no da derecho a prestación por desempleo de forma inmediata","Sí, pero solo cobra el 50%","Sí, presentando una carta de disculpas"], correct:1, explanation:"Previene que los trabajadores abandonen voluntariamente sus puestos con el objetivo deliberado de cobrar el subsidio público.", noShuffle:false },
  { concept_id:"ipe_u4_q29", unit:4, question:"¿Qué periodo mínimo previo de cotización a la Seguridad Social se exige para tener derecho a la 'Prestación Contributiva por Desempleo' (paro) en España?", options:["90 días","Haber cotizado al menos 360 días dentro de los 6 años anteriores a la situación legal de desempleo (lo que da derecho a 120 días de prestación)","2 años ininterrumpidos","No se exige periodo mínimo"], correct:1, explanation:"Por cada tramo adicional de cotización acreditada se amplía la duración del paro hasta un máximo legal de 2 años (720 días).", noShuffle:false },
  { concept_id:"ipe_u4_q30", unit:4, question:"¿Qué duración tiene el permiso por 'Nacimiento y Cuidado de Menor' (baja por maternidad/paternidad) en España para ambos progenitores de forma igual e intransferible?", options:["6 semanas para el padre y 16 para la madre","16 semanas de suspensión contractual remuneradas al 100% de la base reguladora para cada uno de los dos progenitores de forma idéntica e intransferible","1 año con reserva de puesto","4 semanas únicamente"], correct:1, explanation:"Las 6 primeras semanas posteriores al parto son de descanso obligatorio ininterrumpido a jornada completa para ambos progenitores.", noShuffle:false },
  { concept_id:"ipe_u4_q31", unit:4, question:"¿Qué es el 'TRADE' (Trabajador Autónomo Económicamente Dependiente) en el régimen de autónomos?", options:["Un autónomo que trabaja en comercio internacional","Aquel trabajador por cuenta propia que realiza su actividad económica percibiendo al menos el 75% de sus ingresos totales de un único cliente o empresa principal, gozando de protecciones legales especiales (contrato por escrito, 18 días de vacaciones)","Un autónomo que no paga cuotas","Un socio de una gran empresa"], correct:1, explanation:"La ley del estatuto del trabajo autónomo (LETA) le otorga una figura intermedia de protección laboral frente a la dependencia económica.", noShuffle:false },
  { concept_id:"ipe_u4_q32", unit:4, question:"¿Qué es un 'Falso Autónomo' en el ámbito del desarrollo de software y por qué es un fraude laboral grave?", options:["Un autónomo que usa un nombre falso","Una persona que trabaja bajo la apariencia formal de autónomo (emitiendo facturas con IVA) pero que en la realidad material opera con dependencia organizativa, sujeción a horarios, medios y directrices de la empresa como un asalariado encubierto","Un autónomo que no tiene ordenador propio","Un estudiante en prácticas"], correct:1, explanation:"La Inspección de Trabajo persigue esta práctica que defrauda cotizaciones sociales; la empresa debe dar de alta al empleado con contrato indefinido y pagar cuotas atrasadas con recargo.", noShuffle:false },
  { concept_id:"ipe_u4_q33", unit:4, question:"¿Cuáles son las cuatro notas o características esenciales que definen la existencia de una relación laboral asalariada frente a un servicio profesional autónomo?", options:["Tener contrato escrito y título universitario","Voluntariedad, Ajenidad (en los frutos y en los riesgos), Dependencia (sujeción al poder de dirección de la empresa) y Retribución salarial periódica","Cobrar en euros y tener jornada fija","Trabajar en la oficina del cliente"], correct:1, explanation:"Si concurren dependencia y ajenidad, los tribunales declaran automáticamente la existencia de un contrato laboral ordinario con todas sus garantías.", noShuffle:false },
  { concept_id:"ipe_u4_q34", unit:4, question:"¿Qué es el 'Comité de Empresa' en la representación colectiva de los trabajadores?", options:["La junta de accionistas de la sociedad","El órgano colegiado representativo del conjunto de los trabajadores en empresas o centros de trabajo que cuenten con 50 o más empleados para la defensa y negociación de sus intereses laborales","El departamento de recursos humanos","Un tribunal de arbitraje"], correct:1, explanation:"Para empresas de entre 11 y 49 trabajadores la representación corresponde a los 'Delegados de Personal'.", noShuffle:false },
  { concept_id:"ipe_u4_q35", unit:4, question:"¿Qué garantías laborales protegen a los representantes legales de los trabajadores (delegados de personal y miembros del comité de empresa)?", options:["Inmunidad diplomática total","Prioridad de permanencia en la empresa en caso de despidos objetivos o EREs, apertura de expediente contradictorio previo a sanciones y prohibición de ser despedidos o discriminados por el ejercicio de sus funciones sindicales","Sueldo vitalicio garantizado","Vacaciones indefinidas"], correct:1, explanation:"Protege la libertad sindical impidiendo que el empresario tome represalias despidiendo a los líderes que negocian mejoras salariales.", noShuffle:false },
  { concept_id:"ipe_u4_q36", unit:4, question:"¿Qué es un 'ERE' (Expediente de Regulación de Empleo) de extinción o Despido Colectivo?", options:["Un examen de selección masivo","El procedimiento legal obligatorio que debe tramitar una empresa cuando planea despedir por causas económicas, técnicas u organizativas a un número de trabajadores que supera los umbrales legales (ej: al menos 10 trabajadores en empresas de menos de 100)","Un permiso de obras","Una bajada de sueldos generalizada"], correct:1, explanation:"Exige un periodo de consultas preceptivo con los representantes sindicales y notificación previa a la Autoridad Laboral.", noShuffle:false },
  { concept_id:"ipe_u4_q37", unit:4, question:"¿Qué es un 'ERTE' (Expediente de Regulación Temporal de Empleo)?", options:["Un despido definitivo masivo","Una medida de flexibilidad interna donde la empresa suspende temporalmente los contratos de trabajo o reduce la jornada laboral de forma temporal por causas de fuerza mayor o productivas, sin extinguir la relación laboral definitiva","Un curso de formación de empresa","Un subsidio sin cotización"], correct:1, explanation:"Muy utilizado durante la pandemia de COVID-19 para preservar el tejido productivo y evitar despidos definitivos traumáticos.", noShuffle:false },
  { concept_id:"ipe_u4_q38", unit:4, question:"¿Qué es el FOGASA (Fondo de Garantía Salarial)?", options:["Un fondo de pensiones privado","Un organismo autónomo adscrito al Ministerio de Trabajo que abona a los trabajadores los salarios e indemnizaciones pendientes de cobro cuando la empresa es declarada legalmente en insolvencia o concurso de acreedores (con límites cuantitativos legales)","Una aseguradora médica privada","Un banco de inversión público"], correct:1, explanation:"Actúa como red de seguridad pública garantizando que los empleados cobren cantidades mínimas tasadas si su empresa quiebra.", noShuffle:false },
  { concept_id:"ipe_u4_q39", unit:4, question:"¿Qué es la 'Modificación Sustancial de Condiciones de Trabajo' (Artículo 41 del Estatuto de los Trabajadores)?", options:["Cambiar de mesa en la oficina","La facultad del empresario de alterar unilateralmente condiciones esenciales (jornada, horario, régimen de trabajo a turnos, sistema de remuneración) alegando probadas razones económicas, técnicas u organizativas, otorgando al trabajador derecho a rescindir el contrato con indemnización de 20 días por año si resulta perjudicado","Un despido disciplinario encubierto","Una subida de sueldo voluntaria"], correct:1, explanation:"Si la modificación lesiona gravemente al empleado, este puede marcharse cobrando indemnización y con derecho a paro.", noShuffle:false },
  { concept_id:"ipe_u4_q40", unit:4, question:"¿Qué es la 'Excedencia Voluntaria' del trabajador?", options:["Un despido con sueldo","El derecho del trabajador con al menos un año de antigüedad en la empresa a solicitar la suspensión de su contrato por un plazo de entre 4 meses y 5 años; no reserva el puesto de trabajo exacto, sino un derecho preferente de reingreso en vacantes de igual o similar categoría","Un año de vacaciones pagadas","Un permiso médico"], correct:1, explanation:"Permite al empleado explorar proyectos personales sin romper definitivamente su vinculación con la empresa.", noShuffle:false },
  { concept_id:"ipe_u4_q41", unit:4, question:"¿Qué es la 'Prevención de Riesgos Laborales' (Ley 31/1995 de PRL) en el entorno de desarrollo de software y oficinas?", options:["Llevar casco y botas de acero para programar","El conjunto de medidas destinadas a evitar daños a la salud derivados del trabajo: en desarrollo de software se enfoca en riesgos ergonómicos (posturas forzadas, dolores lumbares, síndrome del túnel carpiano), fatiga visual frente a pantallas (PVD) y riesgos psicosociales (estrés, burnout)","Un seguro de vida obligatorio","Un control de alcoholemia"], correct:1, explanation:"La empresa está obligada por ley a evaluar el puesto de trabajo, facilitar sillas ergonómicas regulables, descansos visuales periódicos y formación preventiva.", noShuffle:false },
  { concept_id:"ipe_u4_q42", unit:4, question:"¿Qué es la 'Firma del Finiquito con la mención NO CONFORME' por parte del trabajador?", options:["Cometer un delito de desobediencia","Una cautela fundamental que el trabajador debe escribir junto a su firma en la carta de despido o finiquito si no está de acuerdo con las cantidades o las causas del cese, preservando intacto su derecho a demandar judicialmente a la empresa","Rechazar el cobro del cheque bancario","Romper el papel en pedazos"], correct:1, explanation:"Firmar sin la mención 'No conforme' puede ser interpretado como una aceptación extintiva voluntaria que debilita las reclamaciones posteriores ante el juez.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 5 — Formas Jurídicas, Trámites de Constitución y Fiscalidad Básica
  // ════════════════════════════════════════════════════════════════
  { concept_id:"ipe_u5_q1", unit:5, question:"¿Cuál es la diferencia fundamental de responsabilidad patrimonial entre un Empresario Individual (Autónomo) y una Sociedad de Responsabilidad Limitada (S.L.)?", options:["No hay diferencia de responsabilidad","El Autónomo responde de las deudas del negocio con TODO su patrimonio presente y futuro de forma personal e ilimitada; en la S.L. la responsabilidad de los socios está limitada estrictamente al capital aportado a la sociedad salvaguardando sus bienes personales privados","La S.L. tiene responsabilidad ilimitada","El autónomo nunca responde con su casa"], correct:1, explanation:"Constituir una sociedad mercantil actúa como un escudo legal patrimonial frente a eventuales reclamaciones o quiebras comerciales.", noShuffle:false },
  { concept_id:"ipe_u5_q2", unit:5, question:"¿Cuál es el capital social mínimo legal requerido para constituir una Sociedad Limitada (S.L.) en España tras la Ley 'Crea y Crece' (Ley 18/2022)?", options:["3.000 euros obligatorios","1 euro simbólico (con la obligación de destinar el 20% de los beneficios a reserva legal hasta alcanzar los 3.000 euros tradicionales)","60.000 euros","10.000 euros"], correct:1, explanation:"La Ley Crea y Crece eliminó la barrera histórica de los 3.000€ mínimos para facilitar el emprendimiento ágil.", noShuffle:false },
  { concept_id:"ipe_u5_q3", unit:5, question:"¿Cuál es el capital social mínimo exigido para constituir una Sociedad Anónima (S.A.) en España?", options:["3.000 euros","60.000 euros (debiendo estar desembolsado al menos el 25% en el momento de la constitución)","120.000 euros","1 euro"], correct:1, explanation:"La S.A. es una forma societaria diseñada para grandes corporaciones que pueden emitir acciones negociables en bolsa.", noShuffle:false },
  { concept_id:"ipe_u5_q4", unit:5, question:"¿Qué es el 'Certificado Negativo de Denominación Social' y ante qué organismo oficial se solicita para crear una empresa?", options:["Un certificado de antecedentes penales","El documento oficial expedido por el Registro Mercantil Central que certifica que el nombre elegido para la sociedad no coincide ni se confunde con el de ninguna otra empresa existente en España","Un trámite de Hacienda","Una licencia municipal"], correct:1, explanation:"Es el primer paso ineludible para constituir cualquier sociedad mercantil en España.", noShuffle:false },
  { concept_id:"ipe_u5_q5", unit:5, question:"¿Qué documento formal y público formaliza la creación de una sociedad mercantil y debe ser firmado obligatoriamente por los socios fundadores ante Notario?", options:["Un correo electrónico de confirmación","La Escritura Pública de Constitución de la sociedad, acompañada de los Estatutos Sociales aprobados","Un contrato privado de compraventa","El modelo 036 de Hacienda"], correct:1, explanation:"El Notario da fe pública de la legalidad de los estatutos, aportaciones de capital y nombramiento del órgano de administración.", noShuffle:false },
  { concept_id:"ipe_u5_q6", unit:5, question:"¿Dónde debe inscribirse obligatoriamente la Escritura Pública de Constitución para que la sociedad adquiera personalidad jurídica plena?", options:["En el Registro de la Propiedad","En el Registro Mercantil de la provincia donde radique el domicilio social de la empresa","En la comisaría de policía","En el Juzgado de Paz"], correct:1, explanation:"Hasta su inscripción registral formal la sociedad se considera en formación; la inscripción la dota de personalidad jurídica propia.", noShuffle:false },
  { concept_id:"ipe_u5_q7", unit:5, question:"¿Qué son los PAE (Puntos de Atención al Emprendedor) y el sistema CIRCE en España?", options:["Tiendas de ordenadores de empresa","Oficinas públicas y privadas acreditadas que permiten tramitar telemáticamente y de forma integrada la constitución de empresas y altas de autónomos mediante el Documento Único Electrónico (DUE) en cuestión de horas","Puntos de recogida de paquetería","Oficinas de desempleo"], correct:1, explanation:"Ahorra semanas de papeleo físico conectando telemáticamente a Hacienda, Seguridad Social, Notarios y Registro Mercantil en un único proceso.", noShuffle:false },
  { concept_id:"ipe_u5_q8", unit:5, question:"¿Qué es el CIF/NIF de una empresa en España?", options:["El número de cuenta bancaria","El Número de Identificación Fiscal: el código alfanumérico único obligatorio asignado por la Agencia Tributaria para identificar a personas jurídicas a efectos fiscales y mercantiles (ej: B-12345678 para S.L.)","La contraseña del router","El código postal de la sede"], correct:1, explanation:"Se solicita primero como NIF provisional para operar y se convierte en definitivo tras la inscripción en el Registro Mercantil.", noShuffle:false },
  { concept_id:"ipe_u5_q9", unit:5, question:"¿Qué modelos tributarios de Hacienda se utilizan para cursar el alta, modificación o baja en el censo de empresarios y profesionales?", options:["Modelo 036 (declaración ordinaria completa) o Modelo 037 (versión simplificada para personas físicas)","Modelo 100 de IRPF","Modelo 303 de IVA","Modelo 200 de Sociedades"], correct:0, explanation:"El 036/037 comunica formalmente a la Agencia Tributaria el inicio de la actividad económica, epígrafe del IAE y régimen de IVA aplicable.", noShuffle:false },
  { concept_id:"ipe_u5_q10", unit:5, question:"¿Qué es el IAE (Impuesto sobre Actividades Económicas) y qué exención legal universal beneficia a la inmensa mayoría de autónomos y pymes?", options:["Un impuesto obligatorio para todos los ciudadanos","Un tributo local que grava el ejercicio de actividades empresariales; están exentas de pago todas las personas físicas y las sociedades cuya cifra neta de negocio anual sea inferior a 1.000.000 de euros","Un impuesto sobre compras en el extranjero","Un tributo que no existe en España"], correct:1, explanation:"Aunque casi todas las startups están exentas de pago, es obligatorio darse de alta censalmente en el epígrafe correspondiente (ej: Epígrafe 845 para programadores).", noShuffle:false },
  { concept_id:"ipe_u5_q11", unit:5, question:"¿Cómo funciona el Impuesto sobre el Valor Añadido (IVA) para un autónomo o empresa prestadora de servicios de software?", options:["El IVA es un beneficio propio que se queda la empresa","El profesional actúa como mero recaudador tributario intermediario para Hacienda: cobra IVA Repercutido a sus clientes en las facturas (+21%), resta el IVA Soportado deducible en sus compras del negocio y liquida la diferencia trimestralmente ante la AEAT","El IVA se paga una vez cada 10 años","El IVA solo se cobra a particulares extranjeros"], correct:1, explanation:"Si Repercutido > Soportado: se ingresa la diferencia en Hacienda. Si Soportado > Repercutido: queda saldo a compensar o devolver.", noShuffle:false },
  { concept_id:"ipe_u5_q12", unit:5, question:"¿Qué modelo tributario se utiliza para presentar la autoliquidación trimestral del IVA ante la Agencia Tributaria?", options:["Modelo 303 (trimestral) y Modelo 390 (resumen anual informativo)","Modelo 111","Modelo 130","Modelo 200"], correct:0, explanation:"Se presenta en los primeros 20 días de abril, julio, octubre y hasta el 30 de enero para el cuarto trimestre.", noShuffle:false },
  { concept_id:"ipe_u5_q13", unit:5, question:"¿Cuál es el tipo impositivo general del IVA en España aplicable a los servicios profesionales de desarrollo web y consultoría informática?", options:["4% (Superreducido)","10% (Reducido)","21% (Tipo General)","0% (Exento)"], correct:2, explanation:"Los servicios de programación y diseño web tributan formalmente al tipo general del 21% de IVA.", noShuffle:false },
  { concept_id:"ipe_u5_q14", unit:5, question:"¿Qué es el ROI (Registro de Operadores Intracomunitarios) y el número NIF-IVA (VIES)?", options:["Un registro de importadores de petróleo","Un censo oficial que permite a empresas y autónomos realizar operaciones de compra y venta de servicios y bienes con clientes B2B de otros países de la Unión Europea con factura exenta de IVA mediante inversión del sujeto pasivo","Una cuenta bancaria internacional","Un permiso de aduanas"], correct:1, explanation:"Indispensable para facturar servicios de software a clientes en Alemania, Francia o Irlanda sin repercutir IVA español.", noShuffle:false },
  { concept_id:"ipe_u5_q15", unit:5, question:"¿Cómo tributa un Autónomo profesional (persona física) por los beneficios económicos de su actividad económica?", options:["Mediante el Impuesto sobre Sociedades a tipo fijo","A través del IRPF (Impuesto sobre la Renta de las Personas Físicas) en el régimen de Estimación Directa (Normal o Simplificada), aplicando una escala de gravamen progresiva donde a mayores beneficios mayor es el porcentaje de impuestos","No paga impuestos directos","Paga un impuesto fijo de 50€ al año"], correct:1, explanation:"El rendimiento neto (Ingresos íntegros - Gastos fiscalmente deducibles) se suma a la base imponible general del IRPF.", noShuffle:false },
  { concept_id:"ipe_u5_q16", unit:5, question:"¿Qué modelo tributario presentan trimestralmente los autónomos en estimación directa como pago fraccionado a cuenta de su IRPF?", options:["Modelo 130 (20% del rendimiento neto acumulado del año)","Modelo 303","Modelo 115","Modelo 347"], correct:0, explanation:"Anticipa trimestralmente el 20% del beneficio neto obtenido (salvo que aplique retenciones en más del 70% de sus facturas).", noShuffle:false },
  { concept_id:"ipe_u5_q17", unit:5, question:"¿Qué tipo impositivo general grava los beneficios de las empresas mercantiles en el Impuesto sobre Sociedades (IS) en España?", options:["Un tipo progresivo de hasta el 50%","Un tipo impositivo nominal fijo del 25% sobre la base imponible del beneficio contable ajustado (con tipos reducidos del 15% para empresas de nueva creación en sus primeros ejercicios con base positiva)","Un 10% fijo","Cero impuestos"], correct:1, explanation:"La Ley de Startups (Ley 28/2022) redujo además el tipo al 15% durante un máximo de 4 años para empresas emergentes certificadas.", noShuffle:false },
  { concept_id:"ipe_u5_q18", unit:5, question:"¿Qué modelo tributario se utiliza para liquidar anualmente el Impuesto sobre Sociedades ante Hacienda?", options:["Modelo 200 (declaración anual, presentado del 1 al 25 de julio) y Modelo 202 (pagos fraccionados)","Modelo 100 de IRPF","Modelo 303","Modelo 111"], correct:0, explanation:"El modelo 200 es la declaración definitiva del ejercicio fiscal anterior de las personas jurídicas.", noShuffle:false },
  { concept_id:"ipe_u5_q19", unit:5, question:"¿Qué es la 'Tarifa Plana' para nuevos autónomos en la Seguridad Social española?", options:["Un plan de llamadas telefónicas ilimitadas","Una cuota reducida bonificada a la Seguridad Social (habitualmente 80 euros mensuales durante los primeros 12 meses de actividad) para incentivar el alta de nuevos emprendedores por cuenta propia","No pagar nada a la Seguridad Social durante 5 años","Un seguro de desempleo gratuito"], correct:1, explanation:"Prorrogable otros 12 meses si los rendimientos netos del autónomo no superan el Salario Mínimo Interprofesional.", noShuffle:false },
  { concept_id:"ipe_u5_q20", unit:5, question:"¿Cómo funciona el nuevo sistema de cotización de autónomos en el RETA basado en 'Rendimientos Netos Reales' vigente desde 2023?", options:["Todos los autónomos pagan exactamente lo mismo","El autónomo cotiza dentro de una tabla de 15 tramos según sus ingresos reales netos previstos, eligiendo una base de cotización adaptada a sus beneficios que se regulariza anualmente con Hacienda al cerrar el ejercicio","Se cotiza por sorteo","Se paga según la edad del profesional"], correct:1, explanation:"Ajusta la contribución de forma progresiva: quienes ganan menos pagan cuotas más bajas y quienes obtienen mayores ingresos cotizan más.", noShuffle:false },
  { concept_id:"ipe_u5_q21", unit:5, question:"¿Cuáles son los requisitos legales esenciales para que un gasto sea considerado 'Fiscalmente Deducible' en la actividad de un autónomo o empresa?", options:["Tener cualquier ticket de compra sin nombre","Debe estar directamente vinculado y ser necesario para el desarrollo de la actividad económica, hallarse convenientemente justificado mediante FACTURA formal completa con NIF y estar debidamente registrado en los libros contables oficiales","Pagarlo en efectivo siempre","Haber sido comprado en el extranjero"], correct:1, explanation:"Los simples tickets de caja simplificados no sirven ante una inspección de Hacienda; se exige factura nominativa completa.", noShuffle:false },
  { concept_id:"ipe_u5_q22", unit:5, question:"¿Puede un desarrollador web autónomo que trabaja desde su vivienda habitual deducir gastos de suministros (luz, agua, internet, gas)?", options:["No, está terminantemente prohibido","Sí: la ley de reformas urgentes del trabajo autónomo permite deducir el porcentaje resultante de aplicar el 30% a la proporción existente entre los metros cuadrados de la vivienda dedicados formalmente a la actividad y la superficie total del inmueble","Puede deducir el 100% de todas las facturas de la casa","Solo puede deducir la hipoteca completa"], correct:1, explanation:"Si tienes un despacho del 20% de la casa, deduces el 30% del 20% (un 6% del total de las facturas de suministros).", noShuffle:false },
  { concept_id:"ipe_u5_q23", unit:5, question:"¿Qué es el 'Modelo 111' de retenciones que debe presentar un autónomo o empresa?", options:["Una factura proforma","La declaración trimestral mediante la cual la empresa ingresa en Hacienda las retenciones de IRPF que ha practicado previamente en las nóminas de sus empleados o en las facturas de profesionales externos subcontratados","La liquidación del IVA","El informe de beneficios anuales"], correct:1, explanation:"La empresa actúa como recaudadora ingresando el dinero que retuvo a terceros.", noShuffle:false },
  { concept_id:"ipe_u5_q24", unit:5, question:"¿Qué es el 'Modelo 115' de Hacienda?", options:["La declaración del alquiler del local","El modelo trimestral donde el arrendatario autónomo o empresa declara e ingresa en Hacienda las retenciones de IRPF practicadas en las facturas de alquiler del local u oficina comercial que ocupa su negocio","El impuesto de basuras","Un contrato de arrendamiento"], correct:1, explanation:"Obligatorio si tienes una oficina o local alquilado afecto a la actividad empresarial.", noShuffle:false },
  { concept_id:"ipe_u5_q25", unit:5, question:"¿Qué es el 'Modelo 347' de operaciones con terceras personas?", options:["Un balance contable bancario","Una declaración informativa anual que deben presentar empresas y autónomos para detallar todas aquellas compras o ventas de clientes y proveedores con los que se hayan superado los 3.005,06 euros de facturación acumulada durante el año natural","Un impuesto especial sobre sociedades","Una lista de nóminas de empleados"], correct:1, explanation:"Permite a Hacienda contrastar datos cruzados: si la empresa A declara que compró 4.000€ a la empresa B, la empresa B debe declarar la misma cifra exacta de venta.", noShuffle:false },
  { concept_id:"ipe_u5_q26", unit:5, question:"¿Qué datos obligatorios por ley debe contener una 'Factura Completa' válida en España?", options:["Solo el precio final y el nombre del cliente","Número correlativo y serie, fecha de expedición, nombre o razón social completa, NIF/CIF y domicilio fiscal de emisor y receptor, descripción clara de las operaciones, base imponible, tipo impositivo de IVA (y retención de IRPF si procede) y cuota tributaria resultante","Solo la firma manuscrita","Un código QR únicamente"], correct:1, explanation:"La ausencia de NIF del cliente o numeración no correlativa invalida la factura a efectos de deducción fiscal.", noShuffle:false },
  { concept_id:"ipe_u5_q27", unit:5, question:"¿Qué es la 'Factura Proforma' frente a una factura ordinaria definitiva?", options:["Una factura para profesionales","Un documento puramente informativo y provisional sin validez contable ni fiscal que actúa como un presupuesto u oferta comercial previa detallada antes de la aceptación y pago por parte del cliente","Una factura electrónica certificada","Una factura duplicada"], correct:1, explanation:"No se registra en los libros de contabilidad ni devenga IVA hasta que se emite la factura definitiva real.", noShuffle:false },
  { concept_id:"ipe_u5_q28", unit:5, question:"¿Qué es una 'Factura Rectificativa' (antiguamente llamada nota de abono)?", options:["Una factura con tachones a bolígrafo","El único documento formal admitido legalmente para corregir errores, modificar bases imponibles o anular facturas ordinarias emitidas previamente que contenían fallos de importe, tipo o devoluciones de mercancía","Romper la factura original y hacer otra con el mismo número","Un correo pidiendo disculpas"], correct:1, explanation:"Toda factura emitida tiene validez legal indeleble; nunca debe borrarse un número emitido, sino emitir una rectificativa con serie diferenciada.", noShuffle:false },
  { concept_id:"ipe_u5_q29", unit:5, question:"¿Qué es el sistema 'Veri*factu' y la normativa de Facturación Electrónica obligatoria en España (Ley Crea y Crece)?", options:["Un juego de mesa contable","La regulación que exige que todo el software de facturación de pymes y autónomos garantice la inalterabilidad, trazabilidad e integridad de los registros sin posibilidad de doble contabilidad (software de doble uso prohibido) y la obligatoriedad de la factura electrónica B2B","Un antivirus para facturas en PDF","Un impuesto nuevo sobre el software"], correct:1, explanation:"Busca erradicar el fraude fiscal de la caja B y la morosidad comercial entre empresas.", noShuffle:false },
  { concept_id:"ipe_u5_q30", unit:5, question:"¿Qué son los 'Estatutos Sociales' de una empresa mercantil?", options:["Las leyes generales del Estado","El conjunto de normas internas acordadas por los socios fundadores que regulan el funcionamiento orgánico de la sociedad: denominación, objeto social exacto, domicilio, capital, régimen de participaciones, órgano de administración y adopción de acuerdos","El contrato de trabajo de los directores","El manual de bienvenida de los empleados"], correct:1, explanation:"Forman parte inseparable de la escritura de constitución y deben inscribirse en el Registro Mercantil.", noShuffle:false },
  { concept_id:"ipe_u5_q31", unit:5, question:"¿Qué formas puede adoptar el Órgano de Administración de una Sociedad Limitada?", options:["Solo puede ser un presidente vitalicio","Administrador Único, varios Administradores Solidarios (cada uno puede firmar y obligar a la empresa individualmente), Administradores Mancomunados (deben firmar juntos necesariamente) o Consejo de Administración (órgano colegiado)","Un tribunal militar","Los clientes de la empresa"], correct:1, explanation:"Elegir administradores solidarios agiliza la operativa diaria pero exige máxima confianza mutua entre los socios.", noShuffle:false },
  { concept_id:"ipe_u5_q32", unit:5, question:"¿Qué responsabilidad legal tienen los administradores de una sociedad frente a las deudas si la empresa entra en causa de disolución y no actúan?", options:["Ninguna responsabilidad, la S.L. siempre los protege","Pueden responder solidariamente con TODO su patrimonio personal privado de las deudas sociales contraídas si no convocan la junta en dos meses para disolver la sociedad o solicitar concurso de acreedores ante pérdidas graves continuadas","La cárcel automática","Pagar una multa de 100 euros"], correct:1, explanation:"La limitación de responsabilidad de la S.L. decae si los administradores cometen negligencia grave o gestionan deslealmente una empresa insolvente.", noShuffle:false },
  { concept_id:"ipe_u5_q33", unit:5, question:"¿Qué es la 'Ley de Segunda Oportunidad' para personas físicas y autónomos en España?", options:["Una segunda oportunidad para repetir un curso escolar","Un mecanismo legal concursal que permite a emprendedores y personas físicas de buena fe renegociar sus deudas o conseguir la exoneración judicial definitiva de las deudas que no pueden pagar (EPI) para volver a empezar sin cargas de por vida","Un préstamo bancario al 50% de interés","Una subvención a fondo perdido"], correct:1, explanation:"Evita que una quiebra empresarial condene a un emprendedor honesto a la exclusión financiera perpetua.", noShuffle:false },
  { concept_id:"ipe_u5_q34", unit:5, question:"¿Qué libros contables y societarios oficiales está obligada a legalizar anualmente una Sociedad Limitada en el Registro Mercantil?", options:["Solo un cuaderno de notas","El Libro Diario, el Libro de Inventarios y Cuentas Anuales, el Libro de Actas de las Juntas Generales y el Libro Registro de Socios","Los folletos de publicidad","Las nóminas de los empleados únicamente"], correct:1, explanation:"Deben presentarse telemáticamente en formato digital en los cuatro meses siguientes al cierre del ejercicio contable.", noShuffle:false },
  { concept_id:"ipe_u5_q35", unit:5, question:"¿Qué es el 'Certificado Digital de Representante de Persona Jurídica' expedido por la FNMT?", options:["Un sello de caucho tradicional","El certificado electrónico emitido a nombre de la empresa y su administrador que permite realizar trámites legales, presentar impuestos, recibir notificaciones telemáticas obligatorias y firmar contratos con plena validez legal ante las administraciones públicas","La clave de la WiFi de la oficina","Una tarjeta de crédito corporativa"], correct:1, explanation:"Todas las sociedades mercantiles están obligadas por ley a relacionarse telemáticamente con la administración.", noShuffle:false },
  { concept_id:"ipe_u5_q36", unit:5, question:"¿Qué es la DEHú (Dirección Electrónica Habilitada única) de las notificaciones públicas?", options:["El buzón físico de correos en la puerta","El portal centralizado en internet donde la Agencia Tributaria, Seguridad Social y demás organismos públicos depositan de forma obligatoria las notificaciones oficiales electrónicas a empresas y profesionales","Una cuenta de correo de Gmail","Un servicio de mensajería privada"], correct:1, explanation:"Si transcurren 10 días naturales desde el depósito sin abrir la notificación, la ley la considera notificada legalmente a todos los efectos administrativos.", noShuffle:false },
  { concept_id:"ipe_u5_q37", unit:5, question:"¿Qué es el Kit Digital financiado con fondos europeos Next Generation EU en España?", options:["Un ordenador portátil que regala el ayuntamiento","Un programa público de subvenciones a fondo perdido gestionado por Red.es para impulsar la digitalización de pymes y autónomos mediante un 'bono digital' para contratar soluciones de desarrollo web, comercio electrónico, ciberseguridad o redes sociales con agentes digitalizadores acreditados","Un software antivirus gratuito","Un curso de mecanografía online"], correct:1, explanation:"Ha financiado miles de proyectos de desarrollo web y digitalización para pequeños negocios en España.", noShuffle:false },
  { concept_id:"ipe_u5_q38", unit:5, question:"¿Qué es la 'Amortización Contable' de un bien de inversión (ej: comprar un servidor o portátil de 2.000€)?", options:["Pagar el ordenador al contado","El registro del gasto deducible distribuido progresivamente a lo largo de los años de vida útil estimada del activo (siguiendo las tablas fiscales de la AEAT) en lugar de deducir el importe total de golpe en el mes de compra","El precio de reventa del equipo","Una avería en la placa base"], correct:1, explanation:"Los bienes de inmovilizado material (> 300€ con uso plurianual) deben amortizarse año a año según su depreciación técnica.", noShuffle:false },
  { concept_id:"ipe_u5_q39", unit:5, question:"¿Qué es la 'Capitalización del Paro' (Pago Único de la prestación por desempleo)?", options:["Cobrar el paro en billetes grandes","La medida que permite a un trabajador desempleado con derecho a prestación contributiva cobrar el 100% del valor total acumulado del paro de golpe en un único pago para destinarlo a la inversión inicial necesaria para constituir una empresa o iniciar actividad como autónomo","Un préstamo que se devuelve al Estado","Una indemnización por despido"], correct:1, explanation:"Una de las principales vías de financiación inicial para emprendedores en España.", noShuffle:false },
  { concept_id:"ipe_u5_q40", unit:5, question:"¿Qué ventaja tiene tributar como Sociedad Limitada frente a Autónomo cuando los beneficios económicos anuales superan los 45.000 - 50.000 euros?", options:["En la S.L. no se pagan impuestos","El tipo impositivo del Impuesto sobre Sociedades es fijo (25% o 15% para nuevas empresas), mientras que en el IRPF de autónomo el tipo marginal progresivo puede superar el 45%-47% en tramos altos de renta","La S.L. tiene subvenciones infinitas","El autónomo no puede emitir facturas altas"], correct:1, explanation:"A partir de cierto volumen de beneficio neto anual reinvertido en la empresa, la estructura societaria ofrece un ahorro fiscal sustancial frente al IRPF individual.", noShuffle:false },
  { concept_id:"ipe_u5_q41", unit:5, question:"¿Qué es la 'Declaración Censal' de alta de una actividad económica y por qué debe realizarse ANTES de comprar el primer ordenador o emitir la primera factura?", options:["Un trámite opcional de fin de año","Porque Hacienda solo admite la deducción fiscal del IVA soportado de los gastos e inversiones de puesta en marcha del negocio si la empresa o autónomo ya estaba formalmente dado de alta censalmente en la AEAT en la fecha de la factura de compra","Para que te den el alta en el ayuntamiento","Para recibir publicidad de Hacienda"], correct:1, explanation:"Comprar el equipamiento informático antes de presentar el modelo 036 impide desgravarse legalmente el IVA de esa factura.", noShuffle:false },
  { concept_id:"ipe_u5_q42", unit:5, question:"¿Cuál es la conclusión fundamental para un desarrollador web recién graduado que decide emprender por cuenta propia?", options:["Que la fiscalidad y la gestión legal no importan si eres buen programador","Que el éxito de un proyecto tecnológico depende tanto de la calidad de su código como del rigor en la gestión administrativa, fiscal, financiera y laboral de la empresa, siendo imprescindible contar con asesoramiento profesional de calidad y control continuo de la tesorería","Que hay que buscar un socio millonario de inmediato","Que es imposible vivir de la tecnología sin trabajar en una gran multinacional"], correct:1, explanation:"Emprender en el sector digital es una aventura apasionante y llena de oportunidades cuando se combina talento técnico con disciplina de gestión y cumplimiento legal riguroso.", noShuffle:false }
];
